import type { RawQ } from "../types";
// Scholar tier (Mutaqaddim and ʿĀlim) nahw and balāgha: difficult iʿrāb with the views of the Basran and Kufan schools, figures of speech in named verses, classical works and the history of the science. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  { id: "xnh-001", s: "nahw", g: 4, d: 7, t: ["irab-difficult", "basran-kufan"], src: "Sībawayh, al-Kitāb, bāb al-ʿaṭf ʿalā ism inna; Ibn al-Anbārī, al-Inṣāf fī Masāʾil al-Khilāf, masʾala on the coordination to inna’s ism", v: "5:69", w: 6, tr: ["comparative"],
    en: ["The highlighted noun is nominative although it is joined to nouns that follow inna. Which analysis is attributed to Sībawayh and the Basrans?", ["It is a mubtadaʾ whose khabar is understood after it, the khabar of inna having been given earlier (niyyat al-taʾkhīr)", "It is joined to the khabar of inna with ʿaṭf", "It is a mistake of the scribes", "It is the khabar of a second inna that was omitted"], "Sībawayh explained the nominative by taqdīm and taʾkhīr in meaning: the khabar of inna is given for the first group, and the noun is a mubtadaʾ whose own khabar is omitted, as in ‘and so are the Ṣābiʾūn’. The Kufans (al-Kisāʾī and al-Farrāʾ) allowed ʿaṭf on the position of the ism of inna before the khabar, at least when the ism is indeclinable, as alladhīna is here. The claim of a scribal slip is a late and rejected view."],
    de: ["Das markierte Nomen steht im Nominativ, obwohl es an Nomen nach inna angeschlossen ist. Welche Analyse wird Sībawayh und den Basrern zugeschrieben?", ["Es ist ein Mubtadaʾ, dessen Ḫabar danach zu ergänzen ist, während das Ḫabar von inna zuvor genannt wurde (niyyat at-taʾḫīr)", "Es ist mit ʿAṭf an das Ḫabar von inna angeschlossen", "Es ist ein Schreibfehler", "Es ist das Ḫabar eines ausgelassenen zweiten inna"], "Sībawayh erklärte den Nominativ durch Taqdīm und Taʾḫīr im Sinn: Das Ḫabar von inna wird für die erste Gruppe genannt, und das Nomen ist ein Mubtadaʾ, dessen eigenes Ḫabar ausgelassen ist, wie in ‚und so auch die Ṣābiʾūn‘. Die Kufaner (al-Kisāʾī und al-Farrāʾ) erlaubten ʿAṭf auf die Stelle des Ism von inna vor dem Ḫabar, zumindest wenn das Ism unveränderlich ist, wie hier alladhīna. Die Behauptung eines Schreibversehens ist eine späte, abgelehnte Ansicht."],
    ar: ["الاسم المظلل مرفوع مع أنه معطوف على أسماء بعد «إنّ». أي تحليل يُنسب إلى سيبويه والبصريين؟", ["مبتدأ خبره محذوف مؤخر في النية، وخبر «إنّ» ذُكر قبله", "معطوف على خبر «إنّ»", "خطأ من الكتّاب", "خبر لـ«إنّ» ثانية محذوفة"], "فسّر سيبويه الرفع بالتقديم والتأخير في المعنى: خبر «إنّ» للمجموعة الأولى، والاسم المظلل مبتدأ حُذف خبره كأنه قيل: والصابئون كذلك. وأجاز الكوفيون (الكسائي والفراء) العطف على محل اسم «إنّ» قبل تمام الخبر ولا سيما إذا كان الاسم مبنيًّا كالاسم الموصول هنا. وزعم خطأ الكتّاب قول متأخر مردود."] },

  { id: "xnh-002", s: "nahw", g: 4, d: 7, t: ["irab-difficult", "madh-qat"], src: "Sībawayh, al-Kitāb, bāb mā yanṣub ʿalā al-taʿẓīm wa-l-madḥ; al-Zamakhsharī, al-Kashshāf, on 2:177", v: "2:177", w: 40,
    en: ["Why is the highlighted noun accusative while the other nouns in this long list are nominative?", ["It is accusative as an object of praise (madḥ) governed by an omitted verb such as ‘I praise’, the series of descriptions being cut off (qaṭʿ)", "It is accusative because it is the object of the verb ‘gave’ in the same verse", "It is accusative because it follows a number", "It is accusative as a ḥāl"], "When a series of descriptions of the same subject is long, Arabic allows a break: the speaker puts one of them into the accusative or the nominative with an omitted verb or subject, to draw attention to it. Sībawayh and al-Zamakhsharī cite this verse. The accusative is therefore a naʿt maqṭūʿ for praise of the steadfast."],
    de: ["Warum steht das markierte Nomen im Akkusativ, während die übrigen Nomen in dieser langen Aufzählung im Nominativ stehen?", ["Es steht im Akkusativ als Objekt des Lobes (madḥ), regiert von einem ausgelassenen Verb wie ‚ich lobe‘, wobei die Reihe der Beschreibungen unterbrochen wird (qaṭʿ)", "Es steht im Akkusativ, weil es Objekt des Verbs ‚gab‘ im selben Vers ist", "Es steht im Akkusativ, weil es auf eine Zahl folgt", "Es steht im Akkusativ als Ḥāl"], "Ist eine Reihe von Beschreibungen desselben Subjekts lang, erlaubt das Arabische einen Bruch: Der Sprecher setzt eines davon mit ausgelassenem Verb oder Subjekt in den Akkusativ oder Nominativ, um es hervorzuheben. Sībawayh und az-Zamaḫšarī führen diesen Vers an. Der Akkusativ ist also ein Naʿt maqṭūʿ zum Lob der Standhaften."],
    ar: ["لماذا نُصب الاسم المظلل بينما رُفعت سائر الأسماء في هذه القائمة الطويلة؟", ["نُصب على المدح بفعل محذوف تقديره أمدح، مع قطع النعت عما قبله", "نُصب لأنه مفعول به للفعل «آتى» في الآية نفسها", "نُصب لأنه يلي عددًا", "نُصب على الحال"], "إذا طالت أوصاف موصوف واحد جاز للعرب أن تقطع بعضها فتنصبه أو ترفعه بفعل أو مبتدأ محذوف لتلفت الانتباه إليه، وقد استشهد بالآية سيبويه والزمخشري. فالنصب نعت مقطوع على المدح للصابرين."] },

  { id: "xnh-003", s: "nahw", g: 4, d: 7, t: ["irab-difficult", "mubtada-khabar"], src: "Sībawayh, al-Kitāb, bāb al-ibtidāʾ and on the khabar with fāʾ; al-Mubarrad, al-Muqtaḍab; Ibn Hishām, Mughnī al-Labīb", v: "24:2", w: 1,
    en: ["The highlighted nominative noun is followed by an imperative with fāʾ. Which analysis of the syntax is attributed to Sībawayh?", ["A mubtadaʾ whose khabar is omitted, e.g. ‘among what is recited to you is …’, the imperative being the explanation of the rule", "A mubtadaʾ whose khabar is the imperative with the fāʾ, because the noun is like a conditional", "A fāʿil of an omitted verb", "A khabar of an omitted mubtadaʾ with no further meaning"], "Sībawayh took the noun as a mubtadaʾ with an omitted khabar of the type ‘in what We have laid down for you’ and the imperative as the statement of the ruling. Other grammarians, including al-Mubarrad, allowed the imperative clause to be the khabar, with the fāʾ added because the mubtadaʾ is a relative-like noun with the sense of a condition. Others preferred the accusative by ishtighāl, but the nominative is the reading preserved."],
    de: ["Auf das markierte Nominativnomen folgt ein Imperativ mit Fāʾ. Welche Analyse der Syntax wird Sībawayh zugeschrieben?", ["Ein Mubtadaʾ mit ausgelassenem Ḫabar, etwa ‚unter dem, was euch vorgetragen wird, ist …‘, wobei der Imperativ die Erläuterung der Regel ist", "Ein Mubtadaʾ, dessen Ḫabar der Imperativ mit Fāʾ ist, weil das Nomen einem Konditional gleicht", "Ein Fāʿil eines ausgelassenen Verbs", "Ein Ḫabar eines ausgelassenen Mubtadaʾ ohne weiteren Sinn"], "Sībawayh nahm das Nomen als Mubtadaʾ mit ausgelassenem Ḫabar der Art ‚in dem, was wir euch auferlegt haben‘ und den Imperativ als Darlegung der Vorschrift. Andere Grammatiker, darunter al-Mubarrad, erlaubten, dass der Imperativsatz das Ḫabar ist, wobei das Fāʾ hinzutritt, weil das Mubtadaʾ ein relativähnliches Nomen mit Bedingungssinn ist. Wieder andere zogen den Akkusativ durch Ištiġāl vor, doch der Nominativ ist die überlieferte Lesart."],
    ar: ["الاسم المظلل مرفوع ويليه فعل أمر مقرون بالفاء. أي تحليل للتركيب يُنسب إلى سيبويه؟", ["مبتدأ خبره محذوف (نحو: فيما يُتلى عليكم)، وفعل الأمر بيان للحكم", "مبتدأ خبره فعل الأمر مقرونًا بالفاء لأن الاسم يشبه الشرط", "فاعل لفعل محذوف", "خبر لمبتدأ محذوف بلا معنى زائد"], "جعل سيبويه الاسم مبتدأ خبره محذوف كأنه قيل: فيما فرضناه عليكم، وفعل الأمر بيانًا للحكم. وأجاز غيره كالمبرد أن تكون جملة الأمر الخبر وزيدت الفاء لشبه المبتدأ بالشرط، ورجّح قوم النصب على الاشتغال، لكن الرفع هو المقروء."] },

  { id: "xnh-004", s: "nahw", g: 4, d: 7, t: ["irab-difficult", "dialects"], src: "Ibn Hishām, Mughnī al-Labīb, on inna; al-Zamakhsharī, al-Kashshāf, on 20:63; al-Farrāʾ, Maʿānī al-Qurʾān", v: "20:63", w: 3,
    en: ["The highlighted dual is nominative with alif although it follows the particle inna. Which of these is a recorded explanation?", ["It follows the dialect of some Arab tribes, such as Banū al-Ḥārith ibn Kaʿb, who keep the alif of the dual in all cases", "It is an accusative with an implied tanwīn", "It is a mistake that copyists should correct", "It is a diptote"], "Grammarians gave several explanations: the dialect of Balḥārith ibn Kaʿb and others that keep the alif of the dual in every case; a pronoun of the situation understood after inna; or that the particle is the light in with the lām separating it from the negation, as in the reading of Ibn Kathīr and Ḥafṣ. The suggestion of a scribal error was rejected by the scholars of qirāʾāt."],
    de: ["Der markierte Dual steht im Nominativ mit Alif, obwohl er auf die Partikel inna folgt. Welche der folgenden ist eine überlieferte Erklärung?", ["Er folgt dem Dialekt einiger arabischer Stämme wie der Banū l-Ḥāriṯ ibn Kaʿb, die das Alif des Duals in allen Fällen behalten", "Er ist ein Akkusativ mit einem gedachten Tanwīn", "Er ist ein Fehler, den Kopisten korrigieren sollten", "Er ist ein Diptotum"], "Die Grammatiker gaben mehrere Erklärungen: den Dialekt von Balḥāriṯ ibn Kaʿb und anderen, die das Alif des Duals in jedem Fall behalten; ein Pronomen der Lage, das nach inna zu ergänzen ist; oder dass die Partikel das leichte in mit dem Lām ist, das es von der Verneinung trennt, wie in der Lesart von Ibn Kaṯīr und Ḥafṣ. Die Annahme eines Schreibfehlers wurde von den Gelehrten der Qirāʾāt abgelehnt."],
    ar: ["المثنى المظلل مرفوع بالألف مع أنه يلي الحرف «إنّ». أي مما يأتي تفسير مأثور؟", ["هو على لغة بعض القبائل كبني الحارث بن كعب الذين يلزمون المثنى الألف في أحواله كلها", "هو منصوب بتنوين مقدر", "هو خطأ ينبغي أن يصححه النساخ", "هو ممنوع من الصرف"], "ذكر النحاة وجوهًا: لغة بلحارث بن كعب وغيرهم ممن يلزم المثنى الألف في كل الأحوال، أو ضمير الشأن المقدر بعد «إنّ»، أو أن الحرف «إنْ» المخففة واللام الفارقة بينها وبين النافية كما في قراءة ابن كثير وحفص. أما دعوى الخطأ من الكتّاب فردّها أهل القراءات."] },

  { id: "xnh-005", s: "nahw", g: 4, d: 7, t: ["irab-difficult", "tamanni"], src: "Sībawayh, al-Kitāb, bāb al-jawāb bi-l-wāw; Ibn Hishām, Awḍaḥ al-Masālik, bāb al-nawāṣib; al-Dānī, al-Taysīr", v: "6:27", w: 11,
    en: ["In the reading of Ḥafṣ the highlighted verb is accusative after wāw in the wish clause. How do the Basrans explain the accusative?", ["By an understood an after the wāw of accompaniment (wāw al-maʿiyya) in the answer to a wish (tamannī)", "By the particle laytanā governing it directly", "By the particle lā, which always governs the accusative", "By a jussive that was changed to accusative for rhyme"], "In an answer to a wish, a verb after the fāʾ or the wāw of accompaniment is put in the subjunctive by an understood an. The wāw means ‘and in conjunction with’: they wish to be returned while not denying and being believers. Others read the verb nominative (a new statement), and the grammarians discuss the meaning of both."],
    de: ["In der Lesart von Ḥafṣ steht das markierte Verb im Akkusativ (Subjunktiv) nach dem Wāw im Wunschsatz. Wie erklären die Basrer den Akkusativ?", ["Durch ein ergänztes an nach dem Wāw der Begleitung (wāw al-maʿiyya) in der Antwort auf einen Wunsch (tamannī)", "Durch die Partikel laitanā, die es unmittelbar regiert", "Durch die Partikel lā, die immer den Akkusativ regiert", "Durch einen Jussiv, der des Reims wegen in den Akkusativ geändert wurde"], "In einer Antwort auf einen Wunsch steht ein Verb nach dem Fāʾ oder dem Wāw der Begleitung durch ein ergänztes an im Subjunktiv. Das Wāw bedeutet ‚und zugleich mit‘: Sie wünschen, zurückgebracht zu werden, ohne zu leugnen und als Gläubige. Andere lesen das Verb im Nominativ (eine neue Aussage), und die Grammatiker diskutieren den Sinn beider."],
    ar: ["في قراءة حفص نُصب الفعل المظلل بعد الواو في جملة التمني. كيف يفسّر البصريون النصب؟", ["بـ«أن» مضمرة بعد واو المعية في جواب التمني", "بـ«ليت» التي تعمل فيه مباشرة", "بـ«لا» التي تنصب دائمًا", "بجزم تحوّل إلى النصب للقافية"], "في جواب التمني ينتصب الفعل بعد الفاء أو واو المعية بـ«أن» مضمرة، والواو بمعنى «مع»: يتمنون الرد مع عدم التكذيب وكونهم من المؤمنين. وقرأ آخرون بالرفع على الاستئناف، ويناقش النحاة معنى القراءتين."] },

  { id: "xnh-006", s: "nahw", g: 4, d: 6, t: ["irab-difficult", "kana-tamma"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, bāb kāna wa-akhawātuhā (kāna al-tāmma); al-Zamakhsharī, al-Kashshāf", v: "2:280", w: 2,
    en: ["How is the highlighted verb ‘be’ analysed here, followed by a nominative noun and no accusative khabar?", ["As a kāna tāmma (complete), meaning ‘there is’ or ‘occurs’, with the nominative noun as its fāʿil", "As a kāna nāqiṣa with an omitted khabar", "As an auxiliary of the past with no function", "As a particle of condition only"], "Kāna has two uses: the incomplete (nāqiṣa), needing a khabar, and the complete (tāmma), meaning to exist or to occur, with a fāʿil. Here the noun after it is nominative and nothing is missing, so it is tāmma: ‘if there is someone in difficulty’. In the reading with the accusative, the verb would be incomplete."],
    de: ["Wie wird das markierte Verb ‚sein‘ hier analysiert, auf das ein Nominativnomen und kein Akkusativ-Ḫabar folgt?", ["Als kāna tāmma (vollständig) mit der Bedeutung ‚es gibt‘ oder ‚es tritt ein‘, wobei das Nominativnomen sein Fāʿil ist", "Als kāna nāqiṣa mit ausgelassenem Ḫabar", "Als Hilfsverb der Vergangenheit ohne Funktion", "Nur als Bedingungspartikel"], "Kāna hat zwei Verwendungen: die unvollständige (nāqiṣa), die ein Ḫabar braucht, und die vollständige (tāmma) mit der Bedeutung ‚existieren‘ oder ‚eintreten‘, mit einem Fāʿil. Hier ist das Nomen danach im Nominativ und nichts fehlt, also ist es tāmma: ‚wenn jemand in Bedrängnis ist‘. In der Lesart mit dem Akkusativ wäre das Verb unvollständig."],
    ar: ["كيف يُحلَّل الفعل «كان» المظلل هنا وبعده اسم مرفوع ولا خبر منصوب؟", ["«كان» تامة بمعنى وُجد أو حصل، والاسم المرفوع فاعلها", "«كان» ناقصة خبرها محذوف", "فعل ماض مساعد لا عمل له", "أداة شرط فقط"], "لـ«كان» استعمالان: الناقصة وتحتاج خبرًا، والتامة بمعنى وُجد وحدث وتكتفي بفاعل. وهنا الاسم بعدها مرفوع ولا نقص فهي تامة: إن وُجد ذو عسرة، ولو نُصب الاسم لكانت ناقصة."] },

  { id: "xnh-007", s: "nahw", g: 4, d: 6, t: ["irab-difficult", "hal"], src: "Sībawayh, al-Kitāb; Ibn Hishām, Mughnī al-Labīb, entry hal; al-Zamakhsharī, al-Kashshāf, on 76:1", v: "76:1", w: 1,
    en: ["What is the meaning of the interrogative particle at the start of this verse, according to many commentators and grammarians?", ["It has the meaning of qad, so the sentence affirms, ‘there has indeed come upon man a long time’", "It asks a real question whose answer is unknown", "It negates what follows", "It expresses a condition"], "Many commentators, such as Ibn ʿAbbās and al-Farrāʾ, take hal here as equivalent to qad (affirmation). Others, such as al-Zamakhsharī, keep the question sense as a question of affirmation (istifhām taqrīrī): ‘Has there not come …?’ and the answer is yes. In either case there is no real doubt."],
    de: ["Welche Bedeutung hat die Fragepartikel am Anfang dieses Verses nach der Ansicht vieler Kommentatoren und Grammatiker?", ["Sie hat die Bedeutung von qad, sodass der Satz bejaht: ‚Gewiss ist über den Menschen eine lange Zeit gekommen‘", "Sie stellt eine echte Frage, deren Antwort unbekannt ist", "Sie verneint das Folgende", "Sie drückt eine Bedingung aus"], "Viele Kommentatoren wie Ibn ʿAbbās und al-Farrāʾ nehmen hal hier als gleichbedeutend mit qad (Bejahung). Andere wie az-Zamaḫšarī behalten den Fragesinn als Bestätigungsfrage (istifhām taqrīrī): ‚Ist nicht gekommen …?‘, und die Antwort lautet ja. In beiden Fällen gibt es keinen echten Zweifel."],
    ar: ["ما معنى أداة الاستفهام في أول هذه الآية عند كثير من المفسرين والنحاة؟", ["هي بمعنى «قد» فالجملة إثبات لمرور مدة طويلة من الزمن على الإنسان", "هي سؤال حقيقي مجهول الجواب", "هي تنفي ما بعدها", "هي تفيد الشرط"], "حمل كثير من المفسرين كابن عباس والفراء «هل» على معنى «قد» أي التحقيق، وأبقى آخرون كالزمخشري معنى الاستفهام وجعلوه استفهام تقرير: أليس قد أتى؟ والجواب نعم. وعلى الوجهين لا شك حقيقي في الكلام."] },

  { id: "xnh-008", s: "nahw", g: 4, d: 6, t: ["irab-difficult", "qasam"], src: "Ibn Hishām, Mughnī al-Labīb, on lām al-ibtidāʾ and the oath; Ibn ʿAqīl, Sharḥ Alfiyya", v: "15:72", w: 1,
    en: ["The highlighted word begins with a lām of emphasis and is annexed to a pronoun. How is it analysed?", ["As a mubtadaʾ whose khabar must be omitted, the meaning being ‘by your life is my oath’", "As a fāʿil of an omitted verb", "As a vocative", "As a khabar of inna"], "In the oath formula the noun is a mubtadaʾ, and its khabar (‘my oath’) is omitted by necessity because the oath is understood. The lām is the lām of ibtidāʾ that emphasises the oath. The noun is a verbal noun of the root meaning ‘to live’ and the formula is used for swearing by someone’s life."],
    de: ["Das markierte Wort beginnt mit einem Betonungs-Lām und ist mit einem Pronomen verbunden. Wie wird es analysiert?", ["Als Mubtadaʾ, dessen Ḫabar zwingend ausgelassen werden muss, mit dem Sinn ‚beim Leben des Angesprochenen ist mein Schwur‘", "Als Fāʿil eines ausgelassenen Verbs", "Als Vokativ", "Als Ḫabar von inna"], "In der Schwurformel ist das Nomen ein Mubtadaʾ, und sein Ḫabar (‚mein Schwur‘) wird zwingend ausgelassen, weil der Schwur gedacht ist. Das Lām ist das Lām al-ibtidāʾ, das den Schwur betont. Das Nomen ist ein Verbalnomen der Wurzel mit der Bedeutung ‚leben‘, und die Formel wird gebraucht, um bei jemandes Leben zu schwören."],
    ar: ["الكلمة المظللة تبدأ بلام التوكيد وتضاف إلى ضمير. كيف تُعرب؟", ["مبتدأ خبره محذوف وجوبًا، والمعنى: لعمرك قسمي", "فاعل لفعل محذوف", "منادى", "خبر لـ«إنّ»"], "في صيغة القسم يكون الاسم مبتدأً وخبره (قسمي) محذوف وجوبًا لدلالة القسم عليه، واللام لام الابتداء تفيد توكيد القسم، والاسم مصدر من مادة العيش يُقسم بها بحياة المخاطب."] },

  { id: "xnh-009", s: "nahw", g: 4, d: 7, t: ["irab-difficult", "theology-and-grammar"], tr: ["ashari", "comparative"], src: "al-Zamakhsharī, al-Kashshāf, on 37:96; Fakhr al-Dīn al-Rāzī, al-Tafsīr al-Kabīr; Ibn Hishām, Mughnī al-Labīb, entry mā", v: "37:96", w: 3,
    en: ["The highlighted mā has two main analyses with a theological side. Which statement correctly describes them?", ["It can be a relative pronoun (‘what you make’, the idols), favoured by Muʿtazilī commentators, or a verbal-noun particle (‘your making’), used by many Ashʿarīs to prove that God creates human actions", "It is only a negation, so the verse denies that God made the actions", "It is only an interrogative, so the verse is a question", "It is only a conditional, so the verse is a threat"], "The context concerns Ibrāhīm’s people and the idols they carved. A relative mā means ‘what you carve’; a maṣdarī mā means ‘and your deeds’, which many Ashʿarīs used as a proof text for khalq al-afʿāl. Many Sunni commentators accepted the relative sense and still held the doctrine from other proofs. The grammar allows both."],
    de: ["Das markierte mā hat zwei Hauptanalysen mit einer theologischen Seite. Welche Aussage beschreibt sie richtig?", ["Es kann ein Relativpronomen sein (‚was ihr herstellt‘, die Götzen), von muʿtazilitischen Kommentatoren bevorzugt, oder eine Verbalnomen-Partikel (‚euer Tun‘), von vielen Ašʿariten als Beleg dafür gebraucht, dass Gott die menschlichen Handlungen erschafft", "Es ist nur eine Verneinung, sodass der Vers bestreitet, dass Gott die Handlungen schuf", "Es ist nur ein Fragewort, sodass der Vers eine Frage ist", "Es ist nur eine Bedingung, sodass der Vers eine Drohung ist"], "Der Kontext betrifft das Volk Ibrāhīms und die Götzen, die sie schnitzten. Ein relatives mā bedeutet ‚was ihr schnitzt‘; ein maṣdarī-mā bedeutet ‚und eure Taten‘, was viele Ašʿariten als Belegstelle für ḫalq al-afʿāl nutzten. Viele sunnitische Kommentatoren nahmen den Relativsinn an und hielten die Lehre dennoch aus anderen Belegen. Die Grammatik erlaubt beides."],
    ar: ["للكلمة «ما» المظللة تحليلان رئيسان لهما جانب كلامي. أي عبارة تصفهما على الوجه الصحيح؟", ["قد تكون اسمًا موصولًا (ما تنحتون من الأصنام) ويرجحه معتزلة المفسرين، أو مصدرية (وعملكم) ويستدل بها كثير من الأشاعرة على خلق أفعال العباد", "هي نافية فقط فالآية تنفي أن الله خلق الأفعال", "هي استفهامية فقط فالآية سؤال", "هي شرطية فقط فالآية تهديد"], "السياق في قوم إبراهيم وأصنامهم المنحوتة، فـ«ما» الموصولة بمعنى الذي تنحتونه، والمصدرية بمعنى وعملكم، وقد احتج بها كثير من الأشاعرة على خلق الأفعال، وقبل كثير من المفسرين السنة المعنى الموصول وأثبتوا العقيدة من أدلة أخرى. والنحو يحتمل الوجهين."] },

  { id: "xnh-010", s: "nahw", g: 4, d: 6, t: ["irab-difficult", "tanazu"], src: "Ibn al-Anbārī, al-Inṣāf fī Masāʾil al-Khilāf, masʾala on the competing verbs (al-tanāzuʿ); Ibn ʿAqīl, Sharḥ Alfiyya, bāb al-tanāzuʿ", v: "18:96", w: 19,
    en: ["The highlighted noun can be the object of either of two verbs. How do the Basrans and the Kufans differ?", ["The Basrans give the work to the nearer verb (the second), the Kufans to the first, and the other verb takes a pronoun or has its object omitted", "Both schools give it to the first verb", "Both give it to the second verb and forbid any alternative", "The Basrans say it is an object of neither"], "This is the issue of tanāzuʿ (two verbs sharing one noun). The Basrans prefer the nearer verb because of proximity, the Kufans the first, because of precedence. The verse at hand is a standard illustration: the first verb has a pronoun, so the Basran analysis makes the noun the object of the second verb. Both ways are recorded."],
    de: ["Das markierte Nomen kann Objekt jedes von zwei Verben sein. Wie unterscheiden sich Basrer und Kufaner?", ["Die Basrer geben das Wirken dem näheren Verb (dem zweiten), die Kufaner dem ersten, und das andere Verb nimmt ein Pronomen oder lässt sein Objekt aus", "Beide Schulen geben es dem ersten Verb", "Beide geben es dem zweiten Verb und verbieten jede Alternative", "Die Basrer sagen, es sei Objekt keines von beiden"], "Das ist die Frage des Tanāzuʿ (zwei Verben teilen ein Nomen). Die Basrer bevorzugen das nähere Verb wegen der Nähe, die Kufaner das erste wegen des Vorrangs. Der vorliegende Vers ist ein Standardbeispiel: Das erste Verb hat ein Pronomen, sodass die basrische Analyse das Nomen zum Objekt des zweiten Verbs macht. Beide Wege sind überliefert."],
    ar: ["الاسم المظلل يصح أن يكون مفعولًا لأحد فعلين. كيف يختلف البصريون والكوفيون؟", ["البصريون يعطون العمل للأقرب (الثاني) والكوفيون للأول، ويضمر الآخر أو يُحذف مفعوله", "كلا المذهبين يعطيه للفعل الأول", "كلاهما يعطيه للثاني ويمنع غيره", "يقول البصريون إنه مفعول لا لأحدهما"], "هذه مسألة التنازع في العمل، يرجح البصريون الأقرب لقربه والكوفيون الأول لسبقه، والآية مثال معروف: للفعل الأول ضمير فيكون الاسم مفعولًا للثاني على المذهب البصري. والوجهان مأثوران."] },

  { id: "xnh-011", s: "nahw", g: 4, d: 6, t: ["irab-difficult", "ba-zaida"], src: "Sībawayh, al-Kitāb; Ibn Hishām, Mughnī al-Labīb, entry al-bāʾ", v: "4:171", w: 52,
    en: ["The highlighted word begins with the preposition bi- after the verb ‘suffices’. What is its function?", ["The bāʾ is extra (zāʾida), and the noun is genitive in form but is the fāʿil of ‘suffices’ in meaning (nominative in position)", "The bāʾ is a bāʾ of accompaniment and the noun is a ḥāl", "The bāʾ is a bāʾ of means and the noun is a maf ʿūl bihi", "The bāʾ is for oath and the noun is a muḍāf ilayhi"], "After kafā the subject is often introduced by an added bāʾ, which adds emphasis. The noun is majrūr in form (ʿalā al-lafẓ) and marfūʿ as fāʿil in position (ʿalā al-maḥall). The noun that follows in the accusative is a tamyīz or ḥāl, as grammarians discuss."],
    de: ["Das markierte Wort beginnt mit der Präposition bi- nach dem Verb ‚genügt‘. Welche Funktion hat sie?", ["Das Bāʾ ist überflüssig (zāʾida), und das Nomen ist der Form nach Genitiv, aber dem Sinn nach Fāʿil von ‚genügt‘ (an der Stelle ein Nominativ)", "Das Bāʾ ist ein Bāʾ der Begleitung und das Nomen ein Ḥāl", "Das Bāʾ ist ein Bāʾ des Mittels und das Nomen ein Mafʿūl bihi", "Das Bāʾ dient dem Schwur und das Nomen ist ein Muḍāf ilayhi"], "Nach kafā wird das Subjekt häufig durch ein hinzugefügtes Bāʾ eingeführt, das die Betonung steigert. Das Nomen ist der Form nach majrūr (ʿalā l-lafẓ) und an der Stelle marfūʿ als Fāʿil (ʿalā l-maḥall). Das folgende Akkusativnomen ist ein Tamyīz oder Ḥāl, wie die Grammatiker erörtern."],
    ar: ["الكلمة المظللة تبدأ بحرف الجر الباء بعد فعل الكفاية. ما وظيفتها؟", ["الباء زائدة والاسم مجرور لفظًا وهو فاعل «كفى» محلًّا", "الباء للمصاحبة والاسم حال", "الباء للاستعانة والاسم مفعول به", "الباء للقسم والاسم مضاف إليه"], "يُدخل الفعل «كفى» على فاعله باءً زائدة للتوكيد، فالاسم مجرور لفظًا مرفوع محلًّا على الفاعلية. والاسم المنصوب بعده تمييز أو حال كما يبحث النحاة."] },

  { id: "xnh-012", s: "nahw", g: 4, d: 6, t: ["balagha", "tashbih"], src: "al-Qazwīnī, al-Īḍāḥ fī ʿUlūm al-Balāgha, bāb al-tashbīh; ʿAbd al-Qāhir al-Jurjānī, Asrār al-Balāgha", v: "2:187", w: 9,
    en: ["Which type of simile is this, in which spouses are said to be garments for each other?", ["Tashbīh baligh: the particle and the point of resemblance are both omitted and the two terms are put in apposition", "Tashbīh mursal mujmal: the particle is stated and the point omitted", "Tashbīh tamthīlī: a composite picture is compared", "Istiʿāra makniyya: an object is compared to a living being"], "A simile with the particle and the point of comparison both dropped is called baligh (the strongest), because the two sides are presented as identical. In this case ‘they are your garment’, the closeness, covering and mutual protection are the implied points. The Qazwīnī school ranks this kind highest in force."],
    de: ["Um welchen Typ von Vergleich handelt es sich, wenn Ehegatten füreinander als Gewänder bezeichnet werden?", ["Tashbīh baligh: Die Vergleichspartikel und der Vergleichspunkt sind beide ausgelassen und die zwei Glieder stehen in Apposition", "Tashbīh mursal muǧmal: Die Partikel ist genannt und der Punkt ausgelassen", "Tashbīh tamṯīlī: Ein zusammengesetztes Bild wird verglichen", "Istiʿāra makniyya: Ein Gegenstand wird mit einem Lebewesen verglichen"], "Ein Vergleich, in dem Partikel und Vergleichspunkt beide wegfallen, heißt baligh (der stärkste), weil die beiden Seiten als identisch dargestellt werden. Hier sind ‚sie sind euer Gewand‘ Nähe, Bedeckung und gegenseitiger Schutz die gemeinten Punkte. Die Schule von al-Qazwīnī ordnet diese Art der Wirkung nach am höchsten ein."],
    ar: ["ما نوع التشبيه الذي يُجعل فيه الزوجان لباسًا لبعضهما؟", ["تشبيه بليغ: حُذفت أداته ووجه الشبه وجُعل الطرفان متحدين", "تشبيه مرسل مجمل: ذُكرت الأداة وحُذف الوجه", "تشبيه تمثيلي: صورة مركبة تُشبَّه بصورة", "استعارة مكنية: شُبِّه شيء بكائن حي"], "إذا حُذفت أداة التشبيه ووجهه سُمي بليغًا لأنه يُظهر الطرفين كأنهما شيء واحد، والمقصود هنا القرب والستر والحماية المتبادلة، ويرى القزويني وغيره أنه أقوى أنواع التشبيه."] },

  { id: "xnh-013", s: "nahw", g: 4, d: 6, t: ["balagha", "majaz-mursal"], src: "al-Qazwīnī, al-Īḍāḥ fī ʿUlūm al-Balāgha, bāb al-majāz al-mursal; al-Sakkākī, Miftāḥ al-ʿUlūm", v: "2:19", w: 10,
    en: ["Which figure explains the use of the highlighted word, since people put only the tips of their fingers into their ears?", ["Majāz mursal: the whole is named for the part (the fingers for the fingertips)", "Istiʿāra taṣrīḥiyya", "Kināya", "Tashbīh baligh"], "In majāz mursal the relationship between literal and intended meaning is something other than resemblance. Here it is the relation of whole and part (kulliyya or juziʾiyya): ‘fingers’ stand for the tips that are really put in the ears. There is no simile, so the other options do not apply."],
    de: ["Welche Figur erklärt den Gebrauch des markierten Wortes, da man nur die Fingerspitzen in die Ohren steckt?", ["Maǧāz mursal: Das Ganze wird für den Teil genannt (die Finger für die Fingerspitzen)", "Istiʿāra taṣrīḥiyya", "Kināya", "Tashbīh baligh"], "Beim Maǧāz mursal ist die Beziehung zwischen wörtlicher und gemeinter Bedeutung etwas anderes als Ähnlichkeit. Hier ist es die Beziehung von Ganzem und Teil (kulliyya oder ǧuzʾiyya): ‚Finger‘ stehen für die Spitzen, die wirklich in die Ohren gesteckt werden. Es gibt keinen Vergleich, daher greifen die anderen Optionen nicht."],
    ar: ["أي صورة بيانية تفسّر استعمال الكلمة المظللة، إذ إن الناس لا يضعون في آذانهم إلا أطراف الأصابع؟", ["مجاز مرسل: ذُكر الكل وأُريد الجزء (الأصابع للأنامل)", "استعارة تصريحية", "كناية", "تشبيه بليغ"], "في المجاز المرسل تكون العلاقة بين المعنى الحقيقي والمجازي غير المشابهة، وهنا علاقة الكلية: ذُكرت الأصابع وأُريدت الأنامل التي توضع حقيقةً في الأذن. وليس هنا تشبيه فلا تنطبق الأنواع الأخرى."] },

  { id: "xnh-014", s: "nahw", g: 4, d: 6, t: ["balagha", "majaz-aqli"], src: "al-Qazwīnī, al-Īḍāḥ fī ʿUlūm al-Balāgha, bāb al-majāz al-ʿaqlī; ʿAbd al-Qāhir al-Jurjānī, Asrār al-Balāgha", v: "2:16", w: 8,
    en: ["The verse says that ‘their trade made no profit’. Which figure is this?", ["Majāz ʿaqlī: the profit is attributed to the trade, though it is the traders who profit", "Kināya ʿan ṣifa", "Tashbīh baligh", "Tawriya"], "In a majāz ʿaqlī the verb is attributed to something other than its true doer because of a relationship, here that the trade is the place or cause of profit. The words themselves are used literally; the figure lies in the ascription (isnād), as al-Jurjānī and al-Qazwīnī explain."],
    de: ["Der Vers sagt, ‚ihr Handel brachte keinen Gewinn‘. Welche Figur ist das?", ["Maǧāz ʿaqlī: Der Gewinn wird dem Handel zugeschrieben, obwohl die Händler gewinnen", "Kināya ʿan ṣifa", "Tashbīh baligh", "Tawriya"], "Beim Maǧāz ʿaqlī wird das Verb wegen einer Beziehung etwas anderem als dem wahren Handelnden zugeschrieben, hier weil der Handel Ort oder Ursache des Gewinns ist. Die Wörter selbst werden wörtlich gebraucht; die Figur liegt in der Zuschreibung (isnād), wie al-Ǧurǧānī und al-Qazwīnī erklären."],
    ar: ["تقول الآية إن تجارتهم لم تربح. أي صورة بيانية هذه؟", ["مجاز عقلي: أُسند الربح إلى التجارة وهو للتجار", "كناية عن صفة", "تشبيه بليغ", "توريه"], "في المجاز العقلي يُسند الفعل إلى غير فاعله الحقيقي لعلاقة، وهنا أن التجارة مكان الربح أو سببه، والألفاظ مستعملة في حقيقتها، والمجاز في الإسناد كما يبين الجرجاني والقزويني."] },

  { id: "xnh-015", s: "nahw", g: 4, d: 6, t: ["balagha", "istiara"], src: "al-Qazwīnī, al-Īḍāḥ fī ʿUlūm al-Balāgha, bāb al-istiʿāra; ʿAbd al-Qāhir al-Jurjānī, Asrār al-Balāgha", v: "2:257", w: 7,
    en: ["The highlighted word and ‘the light’ stand for disbelief and faith. Which figure is this?", ["Istiʿāra taṣrīḥiyya aṣliyya: the borrowed terms are stated and the originals (the things compared) are omitted", "Istiʿāra makniyya", "Majāz mursal", "Kināya"], "In an explicit metaphor (taṣrīḥiyya) the thing compared to (the borrowed term) is stated, while the thing compared (here, disbelief and faith) is dropped. It is aṣliyya because the borrowed words are nouns, not verbs. The context makes the intended resemblance clear: darkness hides the path, light shows it."],
    de: ["Das markierte Wort und ‚das Licht‘ stehen für Unglauben und Glauben. Welche Figur ist das?", ["Istiʿāra taṣrīḥiyya aṣliyya: Die entlehnten Ausdrücke werden genannt, und die Originale (das Verglichene) fallen weg", "Istiʿāra makniyya", "Maǧāz mursal", "Kināya"], "In einer ausdrücklichen Metapher (taṣrīḥiyya) wird das, womit verglichen wird (der entlehnte Ausdruck), genannt, während das Verglichene (hier Unglaube und Glaube) wegfällt. Aṣliyya ist sie, weil die entlehnten Wörter Nomen und keine Verben sind. Der Kontext macht die gemeinte Ähnlichkeit klar: Finsternis verbirgt den Weg, Licht zeigt ihn."],
    ar: ["الكلمة المظللة و«النور» يرمزان إلى الكفر والإيمان. أي صورة بيانية هذه؟", ["استعارة تصريحية أصلية: ذُكر المشبَّه به وحُذف المشبَّه", "استعارة مكنية", "مجاز مرسل", "كناية"], "في الاستعارة التصريحية يُذكر المشبَّه به (الظلمات والنور) ويُحذف المشبَّه (الكفر والإيمان)، وهي أصلية لأن اللفظين المستعارين اسمان لا فعلان، والسياق يوضح وجه الشبه: الظلمة تحجب الطريق والنور يكشفه."] },

  { id: "xnh-016", s: "nahw", g: 4, d: 6, t: ["balagha", "iltifat"], src: "al-Zamakhsharī, al-Kashshāf, on Sūrat al-Fātiḥa; Ibn al-Athīr, al-Mathal al-Sāʾir; al-Suyūṭī, al-Itqān", v: "1:5", w: 1,
    en: ["Which rhetorical device is shown by the change in the highlighted word, after four verses speaking of God in the third person?", ["Iltifāt: a shift from the third person (absent) to the second person (direct address)", "Ṭibāq: a pairing of opposites", "Jinās: a play on words", "Ḥadhf: omission of a part of the sentence"], "After praising God as ‘He’ in the first verses, the speech turns to direct address. This iltifāt, as al-Zamakhsharī notes, keeps the listener alert and expresses the movement from praise about God to a plea made to Him. The device is common in the Quran."],
    de: ["Welches rhetorische Mittel zeigt der Wechsel im markierten Wort, nachdem vier Verse von Gott in der dritten Person gesprochen haben?", ["Iltifāt: ein Wechsel von der dritten Person (abwesend) zur zweiten Person (direkte Anrede)", "Ṭibāq: eine Paarung von Gegensätzen", "Ǧinās: ein Wortspiel", "Ḥaḏf: Auslassung eines Satzteils"], "Nachdem Gott in den ersten Versen als ‚er‘ gepriesen wurde, wendet sich die Rede der direkten Anrede zu. Dieser Iltifāt hält, wie az-Zamaḫšarī bemerkt, den Hörer wach und drückt den Übergang vom Lob über Gott zur Bitte an ihn aus. Das Mittel ist im Koran häufig."],
    ar: ["أي أسلوب بلاغي يظهر في تغير الكلمة المظللة بعد أربع آيات تتحدث عن الله بضمير الغائب؟", ["الالتفات: الانتقال من الغيبة إلى الخطاب", "الطباق: الجمع بين ضدين", "الجناس: لعب بالألفاظ", "الحذف: إسقاط جزء من الجملة"], "بعد الثناء على الله بضمير الغائب في الآيات الأولى ينتقل الكلام إلى الخطاب المباشر، وهذا الالتفات كما يقول الزمخشري ينشّط السامع ويعبّر عن الانتقال من الثناء على الله إلى الدعاء إليه، وهو كثير في القرآن."] },

  { id: "xnh-017", s: "nahw", g: 4, d: 6, t: ["balagha", "qasr"], src: "al-Qazwīnī, al-Īḍāḥ fī ʿUlūm al-Balāgha, bāb al-qaṣr; ʿAbd al-Qāhir al-Jurjānī, Dalāʾil al-Iʿjāz", v: "1:5", w: 1,
    en: ["What does the fronting of the object before the verb achieve in the highlighted word?", ["Restriction (qaṣr / ikhtiṣāṣ): worship is limited to God alone", "Only a poetic rhythm", "A softening of the command", "Doubt about the object"], "Putting the object before its verb is normally for specification. In this verse it limits worship and seeking help to God, as al-Jurjānī describes the effect of taqdīm. If the order were normal, the sentence would only state that the speaker worships God without the exclusive sense."],
    de: ["Was bewirkt die Voranstellung des Objekts vor das Verb im markierten Wort?", ["Beschränkung (qaṣr / iḫtiṣāṣ): Die Anbetung wird auf Gott allein begrenzt", "Nur einen dichterischen Rhythmus", "Eine Abschwächung des Befehls", "Zweifel am Objekt"], "Das Voranstellen des Objekts vor sein Verb dient normalerweise der Spezifizierung. In diesem Vers beschränkt es Anbetung und Hilfesuche auf Gott, wie al-Ǧurǧānī die Wirkung des Taqdīm beschreibt. Bei normaler Ordnung würde der Satz nur feststellen, dass der Sprecher Gott anbetet, ohne den ausschließenden Sinn."],
    ar: ["ماذا يفيد تقديم المفعول على الفعل في الكلمة المظللة؟", ["القصر والاختصاص: تخصيص العبادة بالله وحده", "مجرد إيقاع شعري", "تلطيف الأمر", "الشك في المفعول"], "الأصل تأخير المفعول عن الفعل، وتقديمه هنا يفيد القصر فتُخصّ العبادة والاستعانة بالله وحده، كما يبيّن الجرجاني أثر التقديم. ولو جاء على الأصل لأفاد الإخبار بعبادة الله دون معنى الحصر."] },

  { id: "xnh-018", s: "nahw", g: 4, d: 6, t: ["balagha", "kinaya"], src: "al-Qazwīnī, al-Īḍāḥ fī ʿUlūm al-Balāgha, bāb al-kināya; al-Zamakhsharī, al-Kashshāf, on 17:29", v: "17:29", w: 4,
    en: ["The command not to make the hand ‘bound to the neck’ is not literal. Which figure is it, and what does it mean?", ["Kināya ʿan ṣifa: a metaphoric expression for stinginess, while its literal sense is also possible", "Istiʿāra taṣrīḥiyya for generosity", "Majāz mursal for the hand", "Tashbīh tamthīlī for travel"], "Kināya is an expression whose literal meaning is possible but whose intended meaning is something else; here the image of the bound hand signifies miserliness, as the next phrase about opening it fully signifies extravagance. The verse thus teaches the middle way in spending."],
    de: ["Der Befehl, die Hand nicht ‚an den Hals gefesselt‘ zu machen, ist nicht wörtlich gemeint. Welche Figur ist es, und was bedeutet sie?", ["Kināya ʿan ṣifa: ein bildlicher Ausdruck für Geiz, wobei sein Wortsinn ebenfalls möglich ist", "Istiʿāra taṣrīḥiyya für Großzügigkeit", "Maǧāz mursal für die Hand", "Tashbīh tamṯīlī für das Reisen"], "Kināya ist ein Ausdruck, dessen Wortsinn möglich ist, dessen gemeinte Bedeutung aber eine andere ist; hier steht das Bild der gefesselten Hand für Geiz, so wie die folgende Wendung vom völligen Öffnen für Verschwendung steht. Der Vers lehrt so den Mittelweg beim Ausgeben."],
    ar: ["النهي عن جعل اليد مغلولة إلى العنق ليس على الحقيقة. ما الصورة البيانية وما المراد؟", ["كناية عن صفة هي البخل مع جواز المعنى الحقيقي", "استعارة تصريحية عن الكرم", "مجاز مرسل في اليد", "تشبيه تمثيلي للسفر"], "الكناية لفظ أريد به لازم معناه مع جواز إرادة المعنى الحقيقي، وهنا اليد المغلولة كناية عن البخل كما أن بسطها كل البسط كناية عن الإسراف، فتعلّم الآية الوسط في الإنفاق."] },

  { id: "xnh-019", s: "nahw", g: 4, d: 6, t: ["balagha", "tibaq"], src: "al-Qazwīnī, al-Īḍāḥ fī ʿUlūm al-Balāgha, bāb al-badīʿ (al-maḥassināt al-maʿnawiyya); Ibn al-Muʿtazz, Kitāb al-Badīʿ", v: "18:18", w: 2,
    en: ["The highlighted word and the word that follows the next ‘and they’ are opposites. What is the figure?", ["Ṭibāq (muṭābaqa): the pairing of two opposites, ‘awake’ and ‘asleep’", "Jinās tāmm", "Saj‘", "Tashbīh"], "Ṭibāq is the combination of a word and its opposite in one sentence. Here ‘awake’ and ‘asleep’ describe the youths of the cave, whom one would think awake though they are sleeping. It belongs to the branch of badīʿ and adds both beauty and meaning."],
    de: ["Das markierte Wort und das Wort nach dem nächsten ‚und sie‘ sind Gegensätze. Welche Figur ist das?", ["Ṭibāq (muṭābaqa): die Paarung zweier Gegensätze, ‚wach‘ und ‚schlafend‘", "Ǧinās tāmm", "Saǧʿ", "Tashbīh"], "Ṭibāq ist die Verbindung eines Wortes mit seinem Gegenteil in einem Satz. Hier beschreiben ‚wach‘ und ‚schlafend‘ die Jünglinge der Höhle, die man für wach hielte, obwohl sie schlafen. Es gehört zum Zweig des Badīʿ und fügt Schönheit wie Bedeutung hinzu."],
    ar: ["الكلمة المظللة والكلمة التي بعد «وهم» ضدان. ما الصورة البديعية؟", ["طباق (مطابقة): الجمع بين الشيء وضده، أيقاظ ورقود", "جناس تام", "سجع", "تشبيه"], "الطباق الجمع بين اللفظ وضده في جملة واحدة، وهنا اليقظة والرقاد في وصف فتية الكهف الذين يُظنون مستيقظين وهم نيام. وهو من علم البديع ويضيف حسنًا ومعنى."] },

  { id: "xnh-020", s: "nahw", g: 4, d: 6, t: ["balagha", "jinas"], src: "al-Qazwīnī, al-Īḍāḥ fī ʿUlūm al-Balāgha, bāb al-jinās; Ibn al-Muʿtazz, Kitāb al-Badīʿ", v: "30:55", w: 3,
    en: ["The highlighted word is repeated in the same form later in the verse with a different meaning. Which figure is this?", ["Jinās tāmm: identical words with different meanings (the Hour of judgement and an hour of time)", "Ṭibāq: opposite words", "Iltifāt: a change of person", "Taqdīm: fronting"], "In jinās tāmm the two words agree in letters, vowels, number and order but differ in meaning. Here the first means the Last Hour and the second a short period of time. Al-Qazwīnī counts it among the strongest kinds of jinās."],
    de: ["Das markierte Wort wird später im Vers in derselben Form mit anderer Bedeutung wiederholt. Welche Figur ist das?", ["Ǧinās tāmm: gleiche Wörter mit verschiedener Bedeutung (die Stunde des Gerichts und eine Zeitstunde)", "Ṭibāq: gegensätzliche Wörter", "Iltifāt: ein Personenwechsel", "Taqdīm: Voranstellung"], "Beim Ǧinās tāmm stimmen die beiden Wörter in Buchstaben, Vokalen, Zahl und Reihenfolge überein, unterscheiden sich aber in der Bedeutung. Hier bedeutet das erste die Letzte Stunde und das zweite eine kurze Zeitspanne. Al-Qazwīnī zählt es zu den stärksten Arten des Ǧinās."],
    ar: ["الكلمة المظللة تتكرر بصورتها نفسها لاحقًا في الآية بمعنى آخر. ما الصورة البديعية؟", ["جناس تام: لفظان متفقان صورةً مختلفان معنى (الساعة القيامة وساعة من الزمان)", "طباق: لفظان متضادان", "التفات: تغيّر الضمير", "تقديم"], "الجناس التام اتفاق اللفظين في الحروف والحركات والعدد والترتيب مع اختلاف المعنى، فالأولى يوم القيامة والثانية مدة قصيرة من الزمن، ويعدّه القزويني من أقوى أنواع الجناس."] },

  { id: "xnh-021", s: "nahw", g: 4, d: 7, t: ["balagha", "tashbih-tamthili"], src: "ʿAbd al-Qāhir al-Jurjānī, Asrār al-Balāgha, on al-tamthīl; al-Qazwīnī, al-Īḍāḥ", v: "29:41", w: 8,
    en: ["What type of simile is the comparison of those who take protectors besides God with the spider that built a house?", ["Tashbīh tamthīlī: the point of resemblance is a picture drawn from several elements, not from a single feature", "Tashbīh baligh", "Tashbīh ḍimnī", "Istiʿāra makniyya"], "In al-Jurjānī’s analysis tamthīl is a simile in which the point of resemblance is derived from several things together: here the spider’s fragile house, its effort, and what it offers no protection against. The simile is explicitly stated with kāf, so it is not an istiʿāra. The verse concludes that the weakest of houses is the spider’s."],
    de: ["Welcher Typ von Vergleich ist die Gleichsetzung derer, die sich neben Gott Beschützer nehmen, mit der Spinne, die ein Haus baute?", ["Tashbīh tamṯīlī: Der Vergleichspunkt ist ein Bild aus mehreren Elementen, nicht aus einem einzelnen Merkmal", "Tashbīh baligh", "Tashbīh ḍimnī", "Istiʿāra makniyya"], "Nach al-Ǧurǧānī ist Tamṯīl ein Vergleich, dessen Vergleichspunkt aus mehreren Dingen zusammen abgeleitet ist: hier das brüchige Haus der Spinne, ihre Mühe und dass es keinen Schutz bietet. Der Vergleich ist mit kāf ausdrücklich genannt, also keine Istiʿāra. Der Vers schließt, dass das gebrechlichste der Häuser das der Spinne ist."],
    ar: ["ما نوع التشبيه في تمثيل من اتخذوا أولياء من دون الله بالعنكبوت التي بنت بيتًا؟", ["تشبيه تمثيلي: وجه الشبه صورة منتزعة من عدة أمور لا من صفة واحدة", "تشبيه بليغ", "تشبيه ضمني", "استعارة مكنية"], "عند الجرجاني التمثيل تشبيه وجه الشبه فيه منتزع من متعدد: ضعف بيت العنكبوت وجهدها وعدم حمايته من شيء. والتشبيه مصرّح بأداته (الكاف) فليس استعارة، وتختم الآية بوصف هذا البيت بأنه أضعف البيوت."] },

  { id: "xnh-022", s: "nahw", g: 4, d: 7, t: ["balagha", "kinaya-fiqh"], tr: ["hanafi", "shafii", "maliki", "hanbali", "comparative"], src: "al-Ṭabarī, Jāmiʿ al-Bayān, on 5:6; Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṭahāra (touching and wuḍūʾ); Ibn Qudāma, al-Mughnī", v: "5:6", w: 35,
    en: ["The highlighted verb is understood differently by the schools: literal touch or kināya for intercourse. Which statement describes the main positions?", ["The Ḥanafīs read it as kināya for intercourse; the Shāfiʿīs as literal touch that breaks wuḍūʾ; the Mālikīs and Ḥanbalīs hold that touch with desire breaks it", "All schools read it only as touch with no further condition", "All schools read it only as intercourse", "The Ḥanafīs read it as literal touch and the others as intercourse"], "The verb lāmasa can mean touching or be a polite expression (kināya) for sexual intercourse. The Ḥanafīs, with a report from Ibn ʿAbbās, take the latter; the Shāfiʿīs take touch literally, as reported from Ibn ʿUmar and Ibn Masʿūd; the Mālikīs and Ḥanbalīs combine them by requiring desire. The case is a classical example of how a rhetorical decision (haqīqa or kināya) shapes a legal ruling."],
    de: ["Das markierte Verb wird von den Schulen unterschiedlich verstanden: wörtliche Berührung oder Kināya für den Beischlaf. Welche Aussage beschreibt die Hauptpositionen?", ["Die Hanafiten lesen es als Kināya für den Beischlaf; die Schafiiten als wörtliche Berührung, die das Wuḍūʾ ungültig macht; die Malikiten und Hanbaliten sagen, Berührung mit Begierde mache es ungültig", "Alle Schulen lesen es nur als Berührung ohne weitere Bedingung", "Alle Schulen lesen es nur als Beischlaf", "Die Hanafiten lesen es als wörtliche Berührung, die anderen als Beischlaf"], "Das Verb lāmasa kann berühren bedeuten oder ein höflicher Ausdruck (Kināya) für den Beischlaf sein. Die Hanafiten nehmen mit einem Bericht von Ibn ʿAbbās Letzteres; die Schafiiten nehmen die Berührung wörtlich, wie von Ibn ʿUmar und Ibn Masʿūd berichtet; die Malikiten und Hanbaliten verbinden beides, indem sie Begierde verlangen. Der Fall ist ein klassisches Beispiel dafür, wie eine rhetorische Entscheidung (Haqīqa oder Kināya) ein rechtliches Urteil formt."],
    ar: ["يفهم الفعل المظلل فقهاء المذاهب فهمين: اللمس الحقيقي أو الكناية عن الجماع. أي عبارة تصف المواقف الرئيسة؟", ["الحنفية يحملونه على الكناية عن الجماع، والشافعية على اللمس الحقيقي الناقض للوضوء، والمالكية والحنابلة على أن اللمس بشهوة ينقض", "المذاهب كلها تحمله على اللمس دون شرط آخر", "المذاهب كلها تحمله على الجماع", "الحنفية يحملونه على اللمس والباقون على الجماع"], "قد يكون الفعل بمعنى اللمس أو كناية عن الجماع، فحمله الحنفية على الكناية ورووه عن ابن عباس، وحمله الشافعية على اللمس رواية عن ابن عمر وابن مسعود، وجمع المالكية والحنابلة بينهما فاشترطوا الشهوة. وهي مثال كلاسيكي لأثر القرار البلاغي (الحقيقة أو الكناية) في الحكم الفقهي."] },

  { id: "xnh-023", s: "nahw", g: 4, d: 6, t: ["balagha", "majaz-aqli"], src: "al-Qazwīnī, al-Īḍāḥ fī ʿUlūm al-Balāgha, bāb al-majāz al-ʿaqlī", v: "28:4", w: 12,
    en: ["The slaughter of the sons is attributed to Pharaoh, though soldiers carried it out. Which figure is this?", ["Majāz ʿaqlī by attributing the act to its cause (the one who gave the order)", "Majāz mursal by naming the whole for the part", "Istiʿāra taṣrīḥiyya", "Tashbīh tamthīlī"], "In a majāz ʿaqlī the act is ascribed to someone other than its doer because that person is its cause. Pharaoh gave the order, so the slaying is ascribed to him. The words are used in their literal senses, which distinguishes this figure from majāz lughawī."],
    de: ["Das Abschlachten der Söhne wird Pharao zugeschrieben, obwohl Soldaten es ausführten. Welche Figur ist das?", ["Maǧāz ʿaqlī durch Zuschreibung der Tat an ihre Ursache (den, der den Befehl gab)", "Maǧāz mursal durch Nennung des Ganzen für den Teil", "Istiʿāra taṣrīḥiyya", "Tashbīh tamṯīlī"], "Beim Maǧāz ʿaqlī wird die Tat jemandem zugeschrieben, der nicht ihr Ausführender ist, weil er ihre Ursache ist. Pharao gab den Befehl, daher wird das Töten ihm zugeschrieben. Die Wörter werden in ihrem wörtlichen Sinn gebraucht, was diese Figur vom Maǧāz lughawī unterscheidet."],
    ar: ["ذبح الأبناء يُنسب إلى فرعون مع أن الجنود نفذوه. أي صورة هذه؟", ["مجاز عقلي بإسناد الفعل إلى سببه (من أمر به)", "مجاز مرسل بذكر الكل وإرادة الجزء", "استعارة تصريحية", "تشبيه تمثيلي"], "في المجاز العقلي يُنسب الفعل إلى غير فاعله لأنه سببه، فلما أمر فرعون بالقتل نُسب الذبح إليه، والألفاظ على حقيقتها، وبذلك يتميز عن المجاز اللغوي."] },

  { id: "xnh-024", s: "nahw", g: 4, d: 6, t: ["balagha", "iltifat"], src: "al-Zamakhsharī, al-Kashshāf, on 10:22; Ibn al-Athīr, al-Mathal al-Sāʾir", v: "10:22", w: 12,
    en: ["The address ‘you were in the ships’ changes to a third-person verb in the highlighted word. What is the figure and its purpose?", ["Iltifāt from second to third person, to describe the event to others and to show that those sailing are of little account", "Taqdīm of the object for restriction", "Ṭibāq between land and sea", "Ḥadhf of the khabar"], "Al-Zamakhsharī explains the change from ‘you’ to ‘they’ as turning to others to marvel at the sailors’ behaviour, so that the listeners may wonder at their ingratitude in distress and gratitude in safety. The shift also gives variety to the style, an aim of iltifāt."],
    de: ["Die Anrede ‚ihr wart auf den Schiffen‘ wechselt im markierten Wort zu einem Verb in der dritten Person. Was ist die Figur und ihr Zweck?", ["Iltifāt von der zweiten zur dritten Person, um das Geschehen anderen zu beschreiben und zu zeigen, dass die Segelnden wenig zählen", "Taqdīm des Objekts zur Beschränkung", "Ṭibāq zwischen Land und Meer", "Ḥaḏf des Ḫabar"], "Az-Zamaḫšarī erklärt den Wechsel von ‚ihr‘ zu ‚sie‘ als Hinwendung zu anderen, um das Verhalten der Seefahrenden zu bestaunen, sodass die Hörer sich über ihre Undankbarkeit in Sicherheit und ihr Flehen in der Not wundern. Der Wechsel gibt dem Stil zugleich Abwechslung, ein Ziel des Iltifāt."],
    ar: ["ينتقل الخطاب لراكبي السفن إلى فعل غيبة في الكلمة المظللة. ما الصورة وغرضها؟", ["التفات من الخطاب إلى الغيبة لحكاية حالهم للآخرين وإظهار قلة شأن الراكبين", "تقديم المفعول للحصر", "طباق بين البر والبحر", "حذف الخبر"], "يفسّر الزمخشري الانتقال من الخطاب إلى الغيبة بأنه توجّه إلى غيرهم ليتعجبوا من سلوك راكبي البحر وجحودهم في الأمن ودعائهم في الشدة، وفيه تنويع للأسلوب وهو من أغراض الالتفات."] },

  { id: "xnh-025", s: "nahw", g: 4, d: 6, t: ["balagha", "muqabala"], src: "al-Qazwīnī, al-Īḍāḥ fī ʿUlūm al-Balāgha, bāb al-muqābala; Ibn Abī al-Iṣbaʿ, Taḥrīr al-Taḥbīr", v: "9:82", w: 2,
    en: ["The verse sets ‘little’ with ‘laughing’ against ‘much’ with ‘weeping’. What is this figure called, as distinct from a simple ṭibāq?", ["Muqābala: a series of two or more meanings is set against the same number of opposites in order", "Jinās: a play on identical sounds", "Iltifāt: a change of person", "Ījāz: brevity"], "While ṭibāq pairs one word with its opposite, muqābala sets groups against groups in the same order. Here ‘laugh little’ is set against ‘weep much’: the first pair of meanings against their opposites in the reverse sense. The device is cited as a standard example in the books of badīʿ."],
    de: ["Der Vers stellt ‚wenig‘ mit ‚lachen‘ gegen ‚viel‘ mit ‚weinen‘. Wie heißt diese Figur im Unterschied zu einem einfachen Ṭibāq?", ["Muqābala: eine Reihe von zwei oder mehr Bedeutungen wird in gleicher Anzahl und Reihenfolge ihren Gegensätzen gegenübergestellt", "Ǧinās: ein Spiel mit gleichen Lauten", "Iltifāt: ein Personenwechsel", "Īǧāz: Kürze"], "Während Ṭibāq ein Wort mit seinem Gegenteil paart, stellt Muqābala Gruppen gegen Gruppen in derselben Reihenfolge. Hier wird ‚wenig lachen‘ gegen ‚viel weinen‘ gesetzt: das erste Paar von Bedeutungen gegen ihre Gegensätze in umgekehrtem Sinn. Das Mittel gilt in den Büchern des Badīʿ als Standardbeispiel."],
    ar: ["تقابل الآية بين «قليلًا» مع الضحك و«كثيرًا» مع البكاء. ما اسم هذه الصورة في مقابل الطباق المجرد؟", ["مقابلة: يُؤتى بمعنيين أو أكثر ثم بما يقابلها على الترتيب", "جناس: لعب بالأصوات المتماثلة", "التفات: تغير الضمير", "إيجاز: اختصار"], "الطباق يجمع بين لفظ وضده، أما المقابلة فتقابل مجموعة معانٍ بمجموعة مقابلة على الترتيب، وهنا يقابل الضحك القليل بالبكاء الكثير. وهي مثال معروف في كتب البديع."] },

  { id: "xnh-026", s: "nahw", g: 4, d: 6, t: ["idafa", "nahw-theory"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, bāb al-iḍāfa (al-iḍāfa al-lafẓiyya); Ibn Hishām, Awḍaḥ al-Masālik", v: "3:185", w: 3,
    en: ["The highlighted active participle is annexed to its object. How is this annexation classified, and what follows?", ["Iḍāfa lafẓiyya (ghayr maḥḍa): it brings only lightness in speech and does not make the first term definite", "Iḍāfa maʿnawiyya (maḥḍa): it makes the first term definite", "Iḍāfa of a mubtadaʾ to its khabar", "Iḍāfa that requires the genitive of a pronoun"], "An annexation of an active participle to its object, with the sense of present or future, is only verbal: it removes the tanwīn for lightness but does not specify the first noun, so it may still describe an indefinite noun. A true annexation (maʿnawiyya) gives definiteness or specification. The distinction matters for agreement and for the adjective rules."],
    de: ["Das markierte Partizip Aktiv ist mit seinem Objekt verbunden. Wie wird diese Verbindung eingeordnet, und was folgt daraus?", ["Iḍāfa lafẓiyya (ġayr maḥḍa): Sie bringt nur Leichtigkeit im Ausdruck und macht das erste Glied nicht bestimmt", "Iḍāfa maʿnawiyya (maḥḍa): Sie macht das erste Glied bestimmt", "Iḍāfa eines Mubtadaʾ an sein Ḫabar", "Iḍāfa, die den Genitiv eines Pronomens verlangt"], "Eine Verbindung eines Partizips Aktiv mit seinem Objekt im Sinn der Gegenwart oder Zukunft ist nur sprachlich: Sie entfernt das Tanwīn zur Erleichterung, bestimmt aber das erste Nomen nicht, sodass es weiterhin ein unbestimmtes Nomen beschreiben kann. Eine echte Iḍāfa (maʿnawiyya) verleiht Bestimmtheit oder Spezifizierung. Die Unterscheidung wirkt sich auf Kongruenz und Adjektivregeln aus."],
    ar: ["اسم الفاعل المظلل مضاف إلى مفعوله. كيف تُصنَّف هذه الإضافة وما أثرها؟", ["إضافة لفظية (غير محضة) تفيد التخفيف ولا تعرّف المضاف", "إضافة معنوية (محضة) تعرّف المضاف", "إضافة مبتدأ إلى خبره", "إضافة تقتضي جر الضمير"], "إضافة اسم الفاعل بمعنى الحال أو الاستقبال إلى معموله إضافة لفظية، تحذف التنوين تخفيفًا ولا تكسب المضاف تعريفًا ولا تخصيصًا فيجوز أن يوصف به النكرة، أما الإضافة المعنوية فتفيد التعريف أو التخصيص. ويظهر الفرق في المطابقة وأحكام النعت."] },

  { id: "xnh-027", s: "nahw", g: 4, d: 7, t: ["irab-difficult", "waqf-and-irab"], tr: ["comparative"], src: "al-Ṭabarī, Jāmiʿ al-Bayān, on 3:7; Ibn Hishām, Mughnī al-Labīb; al-Zarkashī, al-Burhān fī ʿUlūm al-Qurʾān", v: "3:7", w: 32,
    en: ["The highlighted nominative noun is analysed in two ways, which affects where one may stop in the verse. What are they?", ["Coordinated with ‘God’ (so the firmly rooted in knowledge also know the interpretation), or a new mubtadaʾ with ‘they say’ as its khabar (so only God knows it)", "A fāʿil of the previous verb and an object of the next verb", "A ḥāl and a tamyīz", "A diptote and a muḍāf ilayhi"], "If the word is coordinated with the name of God, the interpretation is known to both God and the firmly rooted scholars, as Ibn ʿAbbās and Mujāhid are reported to have said; if it begins a new sentence, the interpretation is known to God alone, and the scholars say ‘we believe in it’, as reported from Ubayy, Ibn Masʿūd and ʿĀʾisha. Both views have defenders, and the stop in the verse is chosen accordingly."],
    de: ["Das markierte Nominativnomen wird auf zwei Weisen analysiert, was beeinflusst, wo man im Vers stoppen darf. Welche sind es?", ["An ‚Gott‘ angeschlossen (sodass auch die fest im Wissen Verwurzelten die Deutung kennen) oder ein neues Mubtadaʾ mit ‚sie sagen‘ als Ḫabar (sodass nur Gott sie kennt)", "Ein Fāʿil des vorigen Verbs und ein Objekt des nächsten Verbs", "Ein Ḥāl und ein Tamyīz", "Ein Diptotum und ein Muḍāf ilayhi"], "Ist das Wort an den Namen Gottes angeschlossen, kennen sowohl Gott als auch die fest im Wissen verwurzelten Gelehrten die Deutung, wie von Ibn ʿAbbās und Muǧāhid berichtet; beginnt es einen neuen Satz, kennt nur Gott die Deutung, und die Gelehrten sagen ‚wir glauben daran‘, wie von Ubaiy, Ibn Masʿūd und ʿĀʾiša berichtet. Beide Ansichten haben Verfechter, und der Halt im Vers wird entsprechend gewählt."],
    ar: ["الاسم المرفوع المظلل يُحلَّل بوجهين يتغير بهما موضع الوقف في الآية. ما هما؟", ["معطوف على لفظ الجلالة فيعلم الراسخون التأويل أيضًا، أو مبتدأ جديد خبره جملة القول فلا يعلمه إلا الله", "فاعل للفعل السابق ومفعول للفعل التالي", "حال وتمييز", "ممنوع من الصرف ومضاف إليه"], "إن عُطف على لفظ الجلالة علم الله والراسخون تأويله كما يُروى عن ابن عباس ومجاهد، وإن كان مبتدأ جديدًا اختص الله بعلمه وقال الراسخون آمنا به كما يُروى عن أُبيّ وابن مسعود وعائشة. وللقولين أنصار، ويُختار الوقف بحسب كل منهما."] },

  { id: "xnh-028", s: "nahw", g: 4, d: 6, t: ["classical-works", "basran-kufan"], src: "Ibn al-Anbārī, al-Inṣāf fī Masāʾil al-Khilāf bayn al-Naḥwiyyīn al-Baṣriyyīn wa-l-Kūfiyyīn",
    en: ["Which scholar wrote al-Inṣāf fī Masāʾil al-Khilāf, setting out the disagreements of the Basran and Kufan grammarians with judgments between them?", ["Abū al-Barakāt ibn al-Anbārī", "Sībawayh", "al-Mubarrad", "Ibn Jinnī"], "Ibn al-Anbārī (d. 577 AH) wrote the Inṣāf, in which he presents each issue with the arguments of both schools and usually sides with the Basrans. Sībawayh (al-Kitāb) and al-Mubarrad (al-Muqtaḍab) were earlier and Ibn Jinnī (al-Khaṣāʾiṣ) wrote on the principles of grammar."],
    de: ["Welcher Gelehrte schrieb al-Inṣāf fī Masāʾil al-Ḫilāf, in dem er die Meinungsverschiedenheiten der basrischen und kufischen Grammatiker mit Urteilen darlegt?", ["Abū l-Barakāt Ibn al-Anbārī", "Sībawayh", "Al-Mubarrad", "Ibn Ǧinnī"], "Ibn al-Anbārī (gest. 577 n. H.) schrieb den Inṣāf, in dem er jede Frage mit den Argumenten beider Schulen darstellt und sich meist auf die Seite der Basrer stellt. Sībawayh (al-Kitāb) und al-Mubarrad (al-Muqtaḍab) waren früher, und Ibn Ǧinnī (al-Ḫaṣāʾiṣ) schrieb über die Grundlagen der Grammatik."],
    ar: ["من الذي ألّف «الإنصاف في مسائل الخلاف» الذي يعرض فيه خلافات النحويين البصريين والكوفيين مع الترجيح بينهم؟", ["أبو البركات ابن الأنباري", "سيبويه", "المبرد", "ابن جني"], "ألّف ابن الأنباري (ت 577هـ) الإنصاف وعرض فيه كل مسألة بحجج المذهبين وانتصر في الغالب للبصريين، وسيبويه (الكتاب) والمبرد (المقتضب) أقدم منه، وابن جني (الخصائص) كتب في أصول النحو."] },

  { id: "xnh-029", s: "nahw", g: 4, d: 6, t: ["classical-works", "authors"], src: "Ibn al-Nadīm, al-Fihrist; Ibn Khallikān, Wafayāt al-Aʿyān",
    en: ["Which scholar wrote al-Muqtaḍab, a major Basran work of grammar and morphology, and had a famous rivalry with Thaʿlab of Kūfa?", ["al-Mubarrad", "al-Zajjāj", "Ibn Jinnī", "al-Akhfash"], "Abū al-ʿAbbās al-Mubarrad (d. 285 AH) wrote al-Muqtaḍab and al-Kāmil, and is considered the head of the Basrans of his time, while Thaʿlab (d. 291 AH) led the Kūfan school in Baghdad. Al-Zajjāj was his student, and Ibn Jinnī lived later."],
    de: ["Welcher Gelehrte schrieb al-Muqtaḍab, ein großes basrisches Werk der Grammatik und Morphologie, und hatte eine berühmte Rivalität mit Ṯaʿlab von Kufa?", ["Al-Mubarrad", "Az-Zaǧǧāǧ", "Ibn Ǧinnī", "Al-Aḫfaš"], "Abū l-ʿAbbās al-Mubarrad (gest. 285 n. H.) schrieb al-Muqtaḍab und al-Kāmil und gilt als Haupt der Basrer seiner Zeit, während Ṯaʿlab (gest. 291 n. H.) die kufische Schule in Bagdad leitete. Az-Zaǧǧāǧ war sein Schüler, und Ibn Ǧinnī lebte später."],
    ar: ["من الذي ألّف «المقتضب»، وهو كتاب بصري كبير في النحو والصرف، وله منافسة مشهورة مع ثعلب الكوفي؟", ["المبرد", "الزجاج", "ابن جني", "الأخفش"], "ألّف أبو العباس المبرد (ت 285هـ) «المقتضب» و«الكامل» ويُعدّ رأس البصريين في عصره، بينما قاد ثعلب (ت 291هـ) المدرسة الكوفية في بغداد، وكان الزجاج تلميذه وابن جني متأخرًا."] },

  { id: "xnh-030", s: "nahw", g: 4, d: 6, t: ["history-of-nahw", "abu-al-aswad"], src: "Ibn al-Nadīm, al-Fihrist; al-Zubaydī, Ṭabaqāt al-Naḥwiyyīn wa-l-Lughawiyyīn; Ibn al-Anbārī, Nuzhat al-Alibbāʾ",
    en: ["Who is traditionally credited with beginning the science of Arabic grammar and with placing dots to mark the vowels of the Quran?", ["Abū al-Aswad al-Duʾalī", "al-Khalīl ibn Aḥmad", "Sībawayh", "Ibn Mālik"], "According to the common account, Abū al-Aswad al-Duʾalī (d. 69 AH), at the instruction of ʿAlī or Ziyād, laid down the first rules of grammar and marked vowels with coloured dots. Al-Khalīl later replaced the dots with the vowel signs in use. The attribution is traditional and the details vary in the sources."],
    de: ["Wem wird traditionell der Beginn der arabischen Grammatik und das Setzen von Punkten zur Kennzeichnung der Koranvokale zugeschrieben?", ["Abū l-Aswad ad-Duʾalī", "Al-Ḫalīl ibn Aḥmad", "Sībawayh", "Ibn Mālik"], "Nach dem üblichen Bericht legte Abū l-Aswad ad-Duʾalī (gest. 69 n. H.) auf Weisung von ʿAlī oder Ziyād die ersten Grammatikregeln fest und kennzeichnete Vokale mit farbigen Punkten. Al-Ḫalīl ersetzte die Punkte später durch die heute gebräuchlichen Vokalzeichen. Die Zuschreibung ist überliefert, und die Einzelheiten variieren in den Quellen."],
    ar: ["لمن يُنسب تقليديًّا بدء علم النحو العربي ووضع النقط لضبط حركات المصحف؟", ["أبو الأسود الدؤلي", "الخليل بن أحمد", "سيبويه", "ابن مالك"], "في الرواية المشهورة وضع أبو الأسود الدؤلي (ت 69هـ) بأمر علي أو زياد أولى قواعد النحو وضبط الحركات بنقط ملونة، ثم عوّض الخليل عن النقط بالحركات المعروفة، والنسبة تقليدية وتختلف التفاصيل في المصادر."] },

  { id: "xnh-031", s: "nahw", g: 4, d: 6, t: ["history-of-nahw", "khalil"], src: "Ibn al-Nadīm, al-Fihrist; al-Zubaydī, Ṭabaqāt al-Naḥwiyyīn wa-l-Lughawiyyīn; Ibn Khallikān, Wafayāt al-Aʿyān",
    en: ["Which scholar of Baṣra, teacher of Sībawayh, devised the vowel signs now in use and began the first Arabic dictionary, Kitāb al-ʿAyn?", ["al-Khalīl ibn Aḥmad al-Farāhīdī", "Abū al-Aswad al-Duʾalī", "Ibn Jinnī", "al-Farrāʾ"], "Al-Khalīl (d. c. 170 AH) introduced the small letter-shaped signs for fatḥa, ḍamma, kasra and others, set out the science of prosody and began the dictionary arranged by points of articulation, called al-ʿAyn after its first letter. The Kitāb of Sībawayh preserves much of his teaching."],
    de: ["Welcher Gelehrte aus Basra, Lehrer Sībawayhs, erdachte die heute gebräuchlichen Vokalzeichen und begann das erste arabische Wörterbuch, das Kitāb al-ʿAin?", ["Al-Ḫalīl ibn Aḥmad al-Farāhīdī", "Abū l-Aswad ad-Duʾalī", "Ibn Ǧinnī", "Al-Farrāʾ"], "Al-Ḫalīl (gest. ca. 170 n. H.) führte die kleinen buchstabenförmigen Zeichen für Fatḥa, Ḍamma, Kasra und weitere ein, begründete die Verslehre und begann das nach Artikulationsorten geordnete Wörterbuch, nach seinem ersten Buchstaben al-ʿAin genannt. Das Kitāb von Sībawayh bewahrt viel von seiner Lehre."],
    ar: ["أي عالم من البصرة، أستاذ سيبويه، ابتكر علامات الحركات المستعملة اليوم وبدأ أول معجم عربي هو «كتاب العين»؟", ["الخليل بن أحمد الفراهيدي", "أبو الأسود الدؤلي", "ابن جني", "الفراء"], "أدخل الخليل (ت نحو 170هـ) علامات صغيرة على هيئة الحروف للفتحة والضمة والكسرة وغيرها، ووضع علم العروض، وبدأ المعجم المرتب على مخارج الحروف وسُمي «العين» باسم أول حروفه، ويحفظ «كتاب» سيبويه كثيرًا من علمه."] },

  { id: "xnh-032", s: "nahw", g: 4, d: 6, t: ["history-of-nahw", "sibawayh"], src: "Ibn al-Nadīm, al-Fihrist; al-Zubaydī, Ṭabaqāt al-Naḥwiyyīn wa-l-Lughawiyyīn",
    en: ["How have later grammarians referred to Sībawayh’s al-Kitāb, because of its authority in the science?", ["As ‘the Quran of grammar’ (Qurʾān al-naḥw), or simply al-Kitāb (‘the Book’)", "As ‘the Dīwān of the Arabs’", "As ‘the Muqaddima’", "As ‘the Alfiyya’"], "Sībawayh (Amr ibn ʿUthmān, d. about 180 AH), a Persian-born student of al-Khalīl, wrote a work so complete that it was simply called al-Kitāb. Later grammarians came to call it the Quran of grammar because every later work depends on it."],
    de: ["Wie nannten spätere Grammatiker Sībawayhs al-Kitāb wegen seiner Autorität in der Wissenschaft?", ["‚Den Koran der Grammatik‘ (Qurʾān an-naḥw) oder einfach al-Kitāb (‚das Buch‘)", "‚Das Dīwān der Araber‘", "‚Die Muqaddima‘", "‚Die Alfiyya‘"], "Sībawayh (ʿAmr ibn ʿUṯmān, gest. um 180 n. H.), ein in Persien geborener Schüler al-Ḫalīls, schrieb ein so umfassendes Werk, dass es einfach al-Kitāb hieß. Spätere Grammatiker nannten es den Koran der Grammatik, weil jedes spätere Werk davon abhängt."],
    ar: ["كيف أشار النحاة المتأخرون إلى «كتاب» سيبويه لمكانته في هذا العلم؟", ["بوصفه «قرآن النحو» أو «الكتاب» وحده", "«ديوان العرب»", "«المقدمة»", "«الألفية»"], "ألّف سيبويه (عمرو بن عثمان، ت نحو 180هـ)، وهو فارسي الأصل وتلميذ الخليل، كتابًا شاملًا حتى سُمي «الكتاب» بلا إضافة، وسماه النحاة بعده قرآن النحو لأن كل ما بعده يعتمد عليه."] },

  { id: "xnh-033", s: "nahw", g: 4, d: 7, t: ["basran-kufan", "methodology"], src: "Ibn al-Anbārī, Luma‘ al-Adilla fī Uṣūl al-Naḥw; al-Suyūṭī, al-Iqtirāḥ fī ʿIlm Uṣūl al-Naḥw; Shawqī Ḍayf, al-Madāris al-Naḥwiyya",
    en: ["Which statement correctly describes the usual contrast between the Basran and the Kufan schools in method?", ["The Basrans were stricter, building rules on widespread usage and analogy, while the Kufans accepted rarer usages and individual lines of poetry as a basis for rules", "The Kufans were stricter and the Basrans accepted any usage", "Both schools accepted only the Quran as a source", "The Basrans rejected analogy altogether"], "Traditional accounts say the Basrans, strict in their choice of speakers and relying on qiyās, rejected rare or isolated forms, whereas the Kufans took wider material, including dialects and single verses. The contrast should not be overdrawn, since later grammarians of Baghdad combined both approaches."],
    de: ["Welche Aussage beschreibt den üblichen methodischen Gegensatz zwischen basrischer und kufischer Schule richtig?", ["Die Basrer waren strenger und stützten Regeln auf verbreiteten Gebrauch und Analogie, während die Kufaner seltenere Verwendungen und einzelne Verszeilen als Grundlage von Regeln akzeptierten", "Die Kufaner waren strenger und die Basrer akzeptierten jeden Gebrauch", "Beide Schulen akzeptierten nur den Koran als Quelle", "Die Basrer lehnten die Analogie ganz ab"], "Die überlieferten Darstellungen sagen, die Basrer, streng in der Wahl der Sprecher und auf Qiyās gestützt, hätten seltene oder vereinzelte Formen abgelehnt, während die Kufaner weiteres Material einschließlich Dialekte und einzelner Verse nahmen. Der Gegensatz sollte nicht übertrieben werden, da spätere Grammatiker Bagdads beide Ansätze verbanden."],
    ar: ["أي عبارة تصف على الوجه الصحيح التباين المعتاد في المنهج بين المدرستين البصرية والكوفية؟", ["البصريون أكثر تشددًا يبنون القواعد على المطرد من الكلام والقياس، والكوفيون يقبلون الشاذ والبيت الواحد أساسًا للقواعد", "الكوفيون أشد تشددًا والبصريون يقبلون كل استعمال", "المدرستان لا تقبلان إلا القرآن مصدرًا", "البصريون يرفضون القياس كليًّا"], "تذكر المصادر أن البصريين تشددوا في اختيار من يؤخذ عنهم واعتمدوا القياس فردّوا النادر والشاذ، وأن الكوفيين توسعوا فأخذوا من اللهجات والبيت الواحد. ولا يُبالغ في هذا التباين لأن نحاة بغداد جمعوا بين المنهجين."] },

  { id: "xnh-034", s: "nahw", g: 4, d: 6, t: ["classical-works", "ibn-malik"], src: "Ibn Mālik, al-Alfiyya (Khulāṣat al-Alfiyya); Ibn ʿAqīl, Sharḥ Alfiyya Ibn Mālik",
    en: ["Which poem of grammar, in about a thousand verses, did Ibn Mālik compose, and whose commentary by Ibn ʿAqīl is among the most widely read?", ["al-Alfiyya (Khulāṣat al-Alfiyya)", "al-Ājurrūmiyya", "al-Muqaddima al-Jazariyya", "Mulḥat al-Iʿrāb"], "Ibn Mālik (d. 672 AH) condensed grammar and morphology in the Alfiyya, which became a base of teaching in the madrasas; Ibn ʿAqīl’s commentary and al-Ushmūnī’s are among the best known. The Ājurrūmiyya is a short prose primer, the Jazariyya is on tajwīd and Mulḥat al-Iʿrāb is al-Ḥarīrī’s poem."],
    de: ["Welches Grammatikgedicht in etwa tausend Versen verfasste Ibn Mālik, und dessen Kommentar von Ibn ʿAqīl gehört zu den meistgelesenen?", ["Al-Alfiyya (Ḫulāṣat al-Alfiyya)", "Al-Āǧurrūmiyya", "Al-Muqaddima al-Ǧazariyya", "Mulḥat al-Iʿrāb"], "Ibn Mālik (gest. 672 n. H.) fasste Grammatik und Morphologie in der Alfiyya zusammen, die zur Grundlage des Unterrichts in den Madrasen wurde; die Kommentare von Ibn ʿAqīl und al-Ušmūnī gehören zu den bekanntesten. Die Āǧurrūmiyya ist eine kurze Prosa-Fibel, die Ǧazariyya handelt vom Tağwīd, und Mulḥat al-Iʿrāb ist das Gedicht von al-Ḥarīrī."],
    ar: ["أي منظومة نحوية في نحو ألف بيت نظمها ابن مالك، وشرح ابن عقيل لها من أوسع الشروح تداولًا؟", ["الألفية (خلاصة الألفية)", "الآجرومية", "المقدمة الجزرية", "ملحة الإعراب"], "اختصر ابن مالك (ت 672هـ) النحو والصرف في الألفية فصارت أساس التدريس في المدارس، وشرحا ابن عقيل والأشموني من أشهر شروحها، أما الآجرومية فمتن نثري صغير والجزرية في التجويد وملحة الإعراب منظومة الحريري."] },

  { id: "xnh-035", s: "nahw", g: 4, d: 6, t: ["classical-works", "ibn-hisham"], src: "Ibn Hishām, Mughnī al-Labīb ʿan Kutub al-Aʿārīb; Ibn Khaldūn, al-Muqaddima (on the arabic sciences)",
    en: ["What is Ibn Hishām’s Mughnī al-Labīb known for, among the books of grammar?", ["A reference on the particles and the types of sentences, with their uses, mostly illustrated with Quranic verses", "A short poem for beginners on case endings", "A dictionary of rare words", "A book on prosody"], "Ibn Hishām (d. 761 AH) devoted the first chapter to the particles in alphabetical order, with discussion of their meanings, then to sentences and their positions, and to common errors of grammarians. Grammarians refer to it for difficult passages of the Quran. Ibn Khaldūn praised his work."],
    de: ["Wofür ist Ibn Hišāms Muġnī l-Labīb unter den Grammatikbüchern bekannt?", ["Ein Nachschlagewerk über die Partikeln und die Satzarten mit ihren Verwendungen, meist durch Koranverse veranschaulicht", "Ein kurzes Anfängergedicht über Kasusendungen", "Ein Wörterbuch seltener Wörter", "Ein Buch über Metrik"], "Ibn Hišām (gest. 761 n. H.) widmete das erste Kapitel den Partikeln in alphabetischer Reihenfolge mit Erörterung ihrer Bedeutungen, dann den Sätzen und ihren Stellungen sowie den häufigen Irrtümern der Grammatiker. Grammatiker greifen darauf bei schwierigen Koranstellen zurück. Ibn Ḫaldūn lobte sein Werk."],
    ar: ["بماذا يشتهر «مغني اللبيب» لابن هشام بين كتب النحو؟", ["مرجع في الحروف وأنواع الجمل واستعمالاتها يمثّل غالبًا بآيات القرآن", "منظومة صغيرة للمبتدئين في علامات الإعراب", "معجم لألفاظ غريبة", "كتاب في العروض"], "خصّص ابن هشام (ت 761هـ) الباب الأول للحروف مرتبة هجائيًّا مع بيان معانيها، ثم الجمل ومواقعها وأخطاء النحاة الشائعة، ويُرجع إليه في مشكلات إعراب القرآن، وقد أثنى ابن خلدون على صنيعه."] },

  { id: "xnh-036", s: "nahw", g: 4, d: 7, t: ["balagha", "nazm-theory"], src: "ʿAbd al-Qāhir al-Jurjānī, Dalāʾil al-Iʿjāz; ʿAbd al-Qāhir al-Jurjānī, Asrār al-Balāgha",
    en: ["What is ʿAbd al-Qāhir al-Jurjānī’s main thesis in Dalāʾil al-Iʿjāz?", ["That eloquence lies in the arrangement (naẓm) of words according to the meanings of grammar (maʿānī al-naḥw), not in single words alone", "That the inimitability lies only in the single words", "That the Quran is inimitable only because of its rhyme", "That inimitability lies in the prophecy of the unseen alone"], "Al-Jurjānī (d. 471 AH) argued that excellence is in how words are arranged and related by grammatical meanings: fronting, omission, definiteness, restriction and so on, not in isolated words or sounds. This theory of naẓm became the foundation of the science of maʿānī and strongly influenced the doctrine of Quranic inimitability."],
    de: ["Was ist ʿAbd al-Qāhir al-Ǧurǧānīs Hauptthese in Dalāʾil al-Iʿǧāz?", ["Dass die Beredsamkeit in der Anordnung (naẓm) der Wörter nach den Bedeutungen der Grammatik (maʿānī n-naḥw) liegt, nicht nur in einzelnen Wörtern", "Dass die Unnachahmlichkeit nur in den einzelnen Wörtern liegt", "Dass der Koran nur wegen seines Reims unnachahmlich ist", "Dass die Unnachahmlichkeit allein in der Voraussage des Verborgenen liegt"], "Al-Ǧurǧānī (gest. 471 n. H.) legte dar, dass die Vortrefflichkeit darin liegt, wie Wörter durch grammatische Bedeutungen angeordnet und verbunden werden: Voranstellung, Auslassung, Bestimmtheit, Beschränkung usw., nicht in einzelnen Wörtern oder Klängen. Diese Theorie des Naẓm wurde zur Grundlage der Wissenschaft der Maʿānī und beeinflusste die Lehre von der Unnachahmlichkeit des Korans stark."],
    ar: ["ما الأطروحة الأساسية لعبد القاهر الجرجاني في «دلائل الإعجاز»؟", ["أن البلاغة في النظم أي تعليق الكلم بعضها ببعض على وفق معاني النحو لا في الألفاظ المفردة وحدها", "أن الإعجاز في الألفاظ المفردة وحدها", "أن القرآن معجز بفواصله فقط", "أن الإعجاز في الإخبار بالغيب وحده"], "قرر الجرجاني (ت 471هـ) أن الفضل في كيفية ترتيب الكلمات وربطها بمعاني النحو من تقديم وحذف وتعريف وقصر وغيرها لا في الألفاظ المفردة ولا في الأصوات، وصارت نظرية النظم أساس علم المعاني ولها أثر كبير في مبحث إعجاز القرآن."] },

  { id: "xnh-037", s: "nahw", g: 4, d: 6, t: ["balagha", "branches"], src: "al-Sakkākī, Miftāḥ al-ʿUlūm; al-Qazwīnī, Talkhīṣ al-Miftāḥ and al-Īḍāḥ",
    en: ["Under which of the three branches of balāgha do the studies of simile, metaphor and kināya fall?", ["ʿIlm al-bayān", "ʿIlm al-maʿānī", "ʿIlm al-badīʿ", "ʿIlm al-ʿarūḍ"], "In the arrangement of al-Sakkākī and al-Qazwīnī, ʿilm al-maʿānī studies how the sentence fits the situation, ʿilm al-bayān the ways of expressing one meaning in various forms (tashbīh, majāz, kināya), and ʿilm al-badīʿ the embellishments. Prosody is a separate science."],
    de: ["Unter welchen der drei Zweige der Balāġa fallen die Lehren von Vergleich, Metapher und Kināya?", ["ʿIlm al-bayān", "ʿIlm al-maʿānī", "ʿIlm al-badīʿ", "ʿIlm al-ʿarūḍ"], "In der Anordnung von as-Sakkākī und al-Qazwīnī untersucht ʿilm al-maʿānī, wie der Satz zur Lage passt, ʿilm al-bayān die Wege, eine Bedeutung in verschiedenen Formen auszudrücken (Tashbīh, Maǧāz, Kināya), und ʿilm al-badīʿ die Verzierungen. Die Metrik ist eine eigene Wissenschaft."],
    ar: ["تحت أي علم من علوم البلاغة الثلاثة تدخل مباحث التشبيه والاستعارة والكناية؟", ["علم البيان", "علم المعاني", "علم البديع", "علم العروض"], "في ترتيب السكاكي والقزويني يبحث علم المعاني في مطابقة الكلام لمقتضى الحال، وعلم البيان في طرق أداء المعنى الواحد بصور مختلفة (التشبيه والمجاز والكناية)، وعلم البديع في المحسنات، والعروض علم مستقل."] },

  { id: "xnh-038", s: "nahw", g: 4, d: 6, t: ["classical-works", "zamakhshari"], tr: ["comparative"], src: "al-Zamakhsharī, al-Kashshāf ʿan Ḥaqāʾiq Ghawāmiḍ al-Tanzīl; Ibn al-Munayyir, al-Intiṣāf min al-Kashshāf; Abū Ḥayyān, al-Baḥr al-Muḥīṭ",
    en: ["How is al-Zamakhsharī’s al-Kashshāf regarded in the Sunni tradition?", ["Praised for its linguistic and rhetorical insight, but read with caution because it reflects the author’s Muʿtazilī doctrine, with glosses and rebuttals by later Sunni scholars", "Rejected without exception and never used", "Accepted without reservation as a Sunni commentary", "Considered a book of hadith"], "Al-Zamakhsharī (d. 538 AH) was a master of language and balāgha, and his commentary is full of insights drawn from them; but he was a Muʿtazilī and his creed shapes some interpretations. Sunni scholars such as Ibn al-Munayyir (al-Intiṣāf) and Abū Ḥayyān wrote notes pointing out these places while using his linguistic work."],
    de: ["Wie wird az-Zamaḫšarīs al-Kaššāf in der sunnitischen Tradition betrachtet?", ["Gelobt für seine sprachliche und rhetorische Einsicht, aber mit Vorsicht gelesen, da es die muʿtazilitische Lehre des Autors widerspiegelt, mit Glossen und Widerlegungen späterer sunnitischer Gelehrter", "Ausnahmslos verworfen und nie benutzt", "Ohne Vorbehalt als sunnitischer Kommentar akzeptiert", "Als Hadithbuch betrachtet"], "Az-Zamaḫšarī (gest. 538 n. H.) war ein Meister von Sprache und Balāġa, und sein Kommentar ist voller daraus gezogener Einsichten; er war aber Muʿtazilit, und seine Lehre prägt einige Deutungen. Sunnitische Gelehrte wie Ibn al-Munayyir (al-Intiṣāf) und Abū Ḥayyān schrieben Anmerkungen, die auf diese Stellen hinweisen, und nutzten zugleich seine sprachlichen Arbeiten."],
    ar: ["كيف يُنظر إلى «الكشاف» للزمخشري في التقليد السني؟", ["يُثنى عليه لدقائق اللغة والبلاغة لكن يُقرأ بحذر لأنه يعكس اعتزال مؤلفه، وعليه حواشٍ وردود من علماء سنة", "يُرفض كليًّا ولا يُستعمل أبدًا", "يُقبل بلا تحفظ تفسيرًا سنيًّا", "يُعدّ كتاب حديث"], "كان الزمخشري (ت 538هـ) إمامًا في اللغة والبلاغة وتفسيره حافل بدقائقهما، لكنه معتزلي وتظهر عقيدته في بعض التأويلات، وقد كتب علماء من أهل السنة كابن المنير في «الانتصاف» وأبي حيان تنبيهات على ذلك مع الإفادة من علمه اللغوي."] },

  { id: "xnh-039", s: "nahw", g: 4, d: 7, t: ["classical-works", "ijaz-works"], src: "al-Rummānī, al-Nukat fī Iʿjāz al-Qurʾān; al-Khaṭṭābī, Bayān Iʿjāz al-Qurʾān; ʿAbd al-Qāhir al-Jurjānī, Dalāʾil al-Iʿjāz; al-Bāqillānī, Iʿjāz al-Qurʾān",
    en: ["Which scholar wrote Bayān Iʿjāz al-Qurʾān, one of the classic treatises on the inimitability of the Quran, alongside those of al-Rummānī and al-Jurjānī?", ["al-Khaṭṭābī (Ḥamd ibn Muḥammad)", "al-Bāqillānī", "al-Zamakhsharī", "Ibn Qutayba"], "Al-Khaṭṭābī (d. 388 AH) wrote the Bayān, al-Rummānī (d. 384 AH) the Nukat and al-Jurjānī the Dalāʾil; the three are often published together as ‘Thalāth Rasāʾil fī Iʿjāz al-Qurʾān’. Al-Bāqillānī wrote his own Iʿjāz al-Qurʾān."],
    de: ["Welcher Gelehrte schrieb Bayān Iʿǧāz al-Qurʾān, eine der klassischen Abhandlungen über die Unnachahmlichkeit des Korans, neben denen von ar-Rummānī und al-Ǧurǧānī?", ["Al-Ḫaṭṭābī (Ḥamd ibn Muḥammad)", "Al-Bāqillānī", "Az-Zamaḫšarī", "Ibn Qutaiba"], "Al-Ḫaṭṭābī (gest. 388 n. H.) schrieb den Bayān, ar-Rummānī (gest. 384 n. H.) die Nukat und al-Ǧurǧānī die Dalāʾil; die drei werden oft zusammen als ‚Ṯalāṯ Rasāʾil fī Iʿǧāz al-Qurʾān‘ herausgegeben. Al-Bāqillānī schrieb sein eigenes Iʿǧāz al-Qurʾān."],
    ar: ["من الذي ألّف «بيان إعجاز القرآن» أحد الرسائل الكلاسيكية في إعجاز القرآن إلى جانب رسالتي الرماني والجرجاني؟", ["الخطابي (حمد بن محمد)", "الباقلاني", "الزمخشري", "ابن قتيبة"], "ألّف الخطابي (ت 388هـ) «البيان» وألّف الرماني (ت 384هـ) «النكت» وألّف الجرجاني «الدلائل» وتُنشر الثلاثة معًا غالبًا باسم «ثلاث رسائل في إعجاز القرآن»، أما الباقلاني فله «إعجاز القرآن» مستقل."] },

  { id: "xnh-040", s: "nahw", g: 4, d: 7, t: ["balagha", "majaz-debate"], tr: ["comparative"], src: "al-Qazwīnī, al-Īḍāḥ fī ʿUlūm al-Balāgha; Ibn Taymiyya, al-Īmān al-Kabīr; Ibn al-Qayyim, al-Ṣawāʿiq al-Mursala",
    en: ["Which statement correctly describes the scholarly disagreement over the existence of majāz (figurative usage) in language and the Quran?", ["The majority of rhetoricians and scholars accept it, while some, such as Ibn Taymiyya and Ibn al-Qayyim, reject majāz as a category and treat such uses as part of usage in context", "Everyone agrees that majāz does not exist in the Quran", "Everyone agrees on the same definition and the same list of majāz", "Only the Muʿtazila accepted it, and the rest rejected it"], "Most rhetoricians (al-Zamakhsharī, al-Qazwīnī) and many scholars of all schools accept majāz, including in the Quran. Ibn Taymiyya and Ibn al-Qayyim, among others, argued against the division into ḥaqīqa and majāz, holding that all language use depends on context, and that the division was introduced late. The practical examples are not in dispute, only the category."],
    de: ["Welche Aussage beschreibt die gelehrte Meinungsverschiedenheit über die Existenz des Maǧāz (übertragener Gebrauch) in Sprache und Koran richtig?", ["Die Mehrheit der Rhetoriker und Gelehrten erkennt ihn an, während einige wie Ibn Taimiyya und Ibn al-Qayyim den Maǧāz als Kategorie ablehnen und solche Verwendungen als Teil des Gebrauchs im Kontext behandeln", "Alle sind sich einig, dass es keinen Maǧāz im Koran gibt", "Alle sind sich über dieselbe Definition und dieselbe Liste des Maǧāz einig", "Nur die Muʿtazila erkannte ihn an, die übrigen lehnten ihn ab"], "Die meisten Rhetoriker (az-Zamaḫšarī, al-Qazwīnī) und viele Gelehrte aller Schulen erkennen den Maǧāz an, auch im Koran. Ibn Taimiyya und Ibn al-Qayyim argumentierten unter anderem gegen die Einteilung in Ḥaqīqa und Maǧāz, da aller Sprachgebrauch vom Kontext abhänge und die Einteilung spät aufgekommen sei. Die praktischen Beispiele sind nicht umstritten, nur die Kategorie."],
    ar: ["أي عبارة تصف على الوجه الصحيح الخلاف العلمي في وجود المجاز في اللغة والقرآن؟", ["جمهور البلاغيين والعلماء على إثباته، ومنع بعضهم كابن تيمية وابن القيم المجاز قسمًا واعتبروا هذه الاستعمالات من دلالة السياق", "أجمع العلماء على أنه لا مجاز في القرآن", "اتفق الجميع على تعريف واحد وقائمة واحدة للمجاز", "لم يقل به إلا المعتزلة وأنكره الباقون"], "أثبت أكثر البلاغيين (كالزمخشري والقزويني) وكثير من علماء المذاهب المجاز حتى في القرآن، واعترض ابن تيمية وابن القيم وغيرهما على تقسيم الكلام إلى حقيقة ومجاز، وجعلا الاستعمال كله تابعًا للسياق وأن التقسيم حادث متأخر. والأمثلة العملية لا خلاف عليها وإنما الخلاف في القسمة."] },

  { id: "xnh-041", s: "nahw", g: 4, d: 7, t: ["classical-works", "ibn-jinni"], src: "Ibn Jinnī, al-Khaṣāʾiṣ, bāb al-ishtiqāq al-akbar; Ibn al-Nadīm, al-Fihrist",
    en: ["What is the ‘greater derivation’ (al-ishtiqāq al-akbar) that Ibn Jinnī discusses in al-Khaṣāʾiṣ?", ["The link between roots that share the same letters in different orders, which suggests a shared core meaning", "The derivation of the verb from the verbal noun", "The derivation of plurals from singulars", "The derivation of the participle from the imperfect"], "Besides the ordinary derivation (ishtiqāq ṣaghīr) from one root and the middle one (kabīr) that links words with the same letters in varying order, Ibn Jinnī describes the greater derivation (akbar) linking roots that share two letters and a similar sound and meaning. He treats it as a source of insight rather than a firm rule."],
    de: ["Was ist die ‚größere Ableitung‘ (al-ištiqāq al-akbar), die Ibn Ǧinnī in al-Ḫaṣāʾiṣ erörtert?", ["Die Verbindung zwischen Wurzeln, die dieselben Buchstaben in anderer Reihenfolge teilen, was einen gemeinsamen Kernsinn nahelegt", "Die Ableitung des Verbs vom Verbalnomen", "Die Ableitung von Pluralen aus Singularen", "Die Ableitung des Partizips vom Imperfekt"], "Neben der gewöhnlichen Ableitung (ištiqāq ṣaġīr) aus einer Wurzel und der mittleren (kabīr), die Wörter mit gleichen Buchstaben in wechselnder Reihenfolge verbindet, beschreibt Ibn Ǧinnī die größere Ableitung (akbar), die Wurzeln verbindet, die zwei Buchstaben und einen ähnlichen Klang und Sinn teilen. Er behandelt sie als Quelle von Einsicht und nicht als feste Regel."],
    ar: ["ما الاشتقاق الأكبر الذي يبحثه ابن جني في «الخصائص»؟", ["الصلة بين جذور تشترك في الحروف نفسها بترتيب مختلف مما يوحي بمعنى جوهري مشترك", "اشتقاق الفعل من المصدر", "اشتقاق الجموع من المفردات", "اشتقاق اسم الفاعل من المضارع"], "إلى جانب الاشتقاق الصغير من جذر واحد والاشتقاق الكبير الذي يربط الكلمات المشتركة في الحروف المختلفة في الترتيب، يصف ابن جني الاشتقاق الأكبر الذي يربط جذورًا تشترك في حرفين وتتقارب صوتًا ومعنى، ويراه مصدر فائدة لا قاعدة مطردة."] },
];
